INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C1','kor',1,1,'u1',1,'자음자와 모음자 가르기 — 자음자(파랑)와 모음자(주황)를 알아보고, 받침 없는 글자를 둘로 나누어 자음자와 모음자를 찾기, 소리 없는 ㅇ도 자음자 자리에 온다는 것 알기',ARRAY['2국04-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C2','kor',1,1,'u1',1,'받침 없는 글자 만들기 — 자음자 하나와 모음자 하나를 모아 글자를 만들고 소리를 이어 읽기, 모음자 방향·획 수가 바뀌면 다른 글자가 됨을 알기',ARRAY['2국04-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C3','kor',1,1,'u1',3,'글자의 짜임 — 세로로 긴 모음자(ㅏㅓㅣ…)는 자음자 오른쪽에 나란히, 가로로 긴 모음자(ㅗㅜㅡ…)는 자음자 아래에 쌓는다는 것 알기, 같은 자음자라도 짝 모음자에 따라 자리가 달라짐',ARRAY['2국04-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C4','kor',1,1,'u1',5,'음절표 읽기 — 왼쪽 자음자 줄과 위쪽 모음자 칸이 만나는 곳에 글자가 있다는 것을 알고, 줄과 칸을 따라 빈칸 글자를 찾거나 한 줄을 읽기',ARRAY['2국04-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C5','kor',1,1,'u1',7,'바른 자세로 읽고 쓰기·획순 — 등을 펴고 책과 눈을 한 뼘쯤 띄워 또박또박 읽기, 연필을 바르게 쥐고 공책을 눌러 쓰기, 자음자 먼저·모음자 나중, 위에서 아래로·왼쪽에서 오른쪽으로',ARRAY['2국03-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C6','kor',1,1,'u1',9,'여러 가지 모음자 — ㅐㅔㅒㅖ와 두 모음자가 합쳐진 ㅘㅙㅚㅝㅞㅟㅢ를 알아보고, 글자 속에서 찾거나 그 모음자로 글자 만들기, ㅐ와 ㅔ·합친 모음자의 한쪽만 보는 실수 가르기',ARRAY['2국04-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u1-C7','kor',1,1,'u1',13,'글자를 모아 낱말 만들고 또박또박 읽기 — 자음자·모음자 카드로 글자를 만들고 차례대로 모아 낱말을 만들기, 그림과 낱말 잇기, 짐작하지 않고 글자 하나하나를 또박또박 읽기',ARRAY['2국02-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X01','kor',1,'u1',ARRAY['K1-1-u1-C1','K1-1-u1-C3']::text[],'자음자와 모음자를 가르지 못하거나, 글자 속에서 자음자 자리에 모음자를(모음자 자리에 자음자를) 고른다','파란 카드(자음자)와 주황 카드(모음자)를 두 줄로 나누어 놓고, 글자 하나마다 「파란 친구 하나, 주황 친구 하나」를 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X02','kor',1,'u1',ARRAY['K1-1-u1-C1','K1-1-u1-C2','K1-1-u1-C6']::text[],'모음자의 방향을 바꾸어 본다(ㅏ↔ㅓ, ㅗ↔ㅜ, ㅑ↔ㅕ)','짧은 획이 긴 획의 어느 쪽에 붙었는지 손가락으로 짚기 — 「바깥쪽이면 ㅏ, 안쪽이면 ㅓ」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X03','kor',1,'u1',ARRAY['K1-1-u1-C2','K1-1-u1-C6']::text[],'짧은 획 하나가 더 있고 없음을 놓친다(ㅏ↔ㅑ, ㅓ↔ㅕ, ㅗ↔ㅛ, ㅜ↔ㅠ)','짧은 획 개수를 「하나·둘」 소리 내어 세어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X04','kor',1,'u1',ARRAY['K1-1-u1-C1','K1-1-u1-C2']::text[],'닮은 자음자를 헷갈린다(ㄱ↔ㅋ, ㄷ↔ㅌ, ㅂ↔ㅍ, ㅈ↔ㅊ, ㅇ↔ㅎ)','획이 하나 더 있는지 견주어 보고, 두 소리를 번갈아 크게 내 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X05','kor',1,'u1',ARRAY['K1-1-u1-C3']::text[],'글자의 짜임 자리를 헷갈린다(가로로 긴 모음자를 옆에, 세로로 긴 모음자를 아래에 둔다)','모음자 카드를 세워 보기 — 키가 크면(ㅏㅣ) 옆에 서고, 누우면(ㅗㅜ) 아래에 깔린다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X06','kor',1,'u1',ARRAY['K1-1-u1-C2','K1-1-u1-C4']::text[],'모음자 카드를 돌려 다른 모음자로 읽는다(ㅏ↔ㅗ, ㅓ↔ㅜ, ㅡ↔ㅣ)','카드 윗면에 별표를 붙이고 별표가 위로 오게 놓고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X07','kor',1,'u1',ARRAY['K1-1-u1-C4']::text[],'음절표에서 옆 칸·옆 줄의 글자를 고른다(줄과 칸이 만나는 곳을 놓친다)','왼손 손가락은 자음자 줄, 오른손 손가락은 모음자 칸 — 두 손가락이 만나는 칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X08','kor',1,'u1',ARRAY['K1-1-u1-C2','K1-1-u1-C7']::text[],'모음자는 보지 않고 자음자만 보고 글자나 낱말을 고른다','「자음자가 같아도 모음자가 다르면 다른 글자」 — 모음자에 동그라미 치고 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X09','kor',1,'u1',ARRAY['K1-1-u1-C7']::text[],'글자를 모으는 차례를 바꾸어 다른 낱말을 만든다(비누→누비, 다리→리다)','카드를 왼쪽부터 손가락으로 하나씩 짚으며 소리 내어 모으기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X10','kor',1,'u1',ARRAY['K1-1-u1-C5']::text[],'바른 읽기 자세를 가르지 못한다(턱 괴기·엎드리기·책에 얼굴 붙이기)','등 펴기 · 두 발 바닥에 · 책과 눈 사이 한 뼘 — 세 가지를 손가락으로 세며 앉아 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X11','kor',1,'u1',ARRAY['K1-1-u1-C5']::text[],'바른 쓰기 자세를 가르지 못한다(공책 들고 쓰기·몸 기울이기·얼굴 바짝 대기)','연필 쥔 손, 공책 누른 손, 곧은 허리 — 세 가지를 짝과 서로 봐 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X12','kor',1,'u1',ARRAY['K1-1-u1-C5']::text[],'획순을 거꾸로 쓴다(모음자를 먼저, 아래에서 위로, 오른쪽에서 왼쪽으로)','「위에서 아래로, 왼쪽에서 오른쪽으로, 자음자 먼저」 세 마디를 말하며 공중에 크게 써 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X13','kor',1,'u1',ARRAY['K1-1-u1-C6']::text[],'ㅐ와 ㅔ, ㅒ와 ㅖ를 헷갈린다','ㅐ는 ㅏ와 ㅣ, ㅔ는 ㅓ와 ㅣ가 붙은 모양 — 앞의 모음자를 먼저 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X14','kor',1,'u1',ARRAY['K1-1-u1-C6']::text[],'두 모음자가 합쳐진 모음자(ㅘㅙㅚㅝㅞㅟㅢ)에서 한쪽만 본다','합친 모음자를 두 카드로 떼어 놓았다가 다시 붙여 보기 — 「ㅗ 더하기 ㅏ는 ㅘ」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X15','kor',1,'u1',ARRAY['K1-1-u1-C5','K1-1-u1-C7']::text[],'글자를 하나하나 읽지 않고 그림이나 첫 글자로 짐작해 읽는다','그림을 가리고 손가락으로 글자를 하나씩 짚으며 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u1-X16','kor',1,'u1',ARRAY['K1-1-u1-C1']::text[],'「아·오·이」처럼 소리 없는 ㅇ이 앞에 오는 글자를 모음자 하나로 된 글자라고 여긴다','「오」 카드를 둘로 잘라 보기 — 위에 ㅇ, 아래에 ㅗ, 두 카드가 있어야 글자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#1','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',1,'mc','auto','다음 가운데 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01']::text[],true,'{"seq":1,"concept":"K1-1-u1-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 모음자는 어느 것인가요?","options":[{"t":"ㅏ","correct":true},{"t":"ㄱ","mis":"K1-1-u1-X01"},{"t":"ㅁ","mis":"K1-1-u1-X01"}],"explanation":["ㅏ는 주황색 모음자 친구예요.","ㄱ·ㅁ은 파란색 자음자예요.","모음자는 ㅏ·ㅓ·ㅗ·ㅜ·ㅣ처럼 막대 모양이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 모음자는 어느 것인가요?","options":[{"t":"ㅜ","correct":true},{"t":"ㄴ","mis":"K1-1-u1-X01"},{"t":"ㅅ","mis":"K1-1-u1-X01"}],"explanation":["ㅜ는 모음자예요.","ㄴ·ㅅ은 자음자예요.","모음자는 막대 모양이에요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 모음자는 어느 것인가요?","options":[{"t":"ㅣ","correct":true},{"t":"ㄹ","mis":"K1-1-u1-X01"},{"t":"ㅂ","mis":"K1-1-u1-X01"}],"explanation":["ㅣ는 모음자예요.","ㄹ·ㅂ은 자음자예요.","모음자는 막대 모양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#2','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',1,'mc','auto','다음 가운데 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01']::text[],true,'{"seq":2,"concept":"K1-1-u1-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 자음자는 어느 것인가요?","options":[{"t":"ㄴ","correct":true},{"t":"ㅗ","mis":"K1-1-u1-X01"},{"t":"ㅣ","mis":"K1-1-u1-X01"}],"explanation":["ㄴ은 파란색 자음자 친구예요.","ㅗ·ㅣ는 주황색 모음자예요.","자음자는 글자의 첫소리를 내요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 자음자는 어느 것인가요?","options":[{"t":"ㅂ","correct":true},{"t":"ㅓ","mis":"K1-1-u1-X01"},{"t":"ㅡ","mis":"K1-1-u1-X01"}],"explanation":["ㅂ은 자음자예요.","ㅓ·ㅡ는 모음자예요.","자음자는 글자의 첫소리를 내요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 자음자는 어느 것인가요?","options":[{"t":"ㅈ","correct":true},{"t":"ㅏ","mis":"K1-1-u1-X01"},{"t":"ㅜ","mis":"K1-1-u1-X01"}],"explanation":["ㅈ은 자음자예요.","ㅏ·ㅜ는 모음자예요.","자음자는 글자의 첫소리를 내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#3','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C2',1,'mc','auto','자음자 ㄱ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":3,"kind":"mc","stem":"자음자 ㄱ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄱ","v":"ㅏ","s":null,"lay":true},"options":[{"t":"가","correct":true},{"t":"거","mis":"K1-1-u1-X02"},{"t":"갸","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㄱ과 모음자 ㅏ가 만나면 「가」예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅣ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#4','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',1,'mc','auto','「사」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":4,"kind":"mc","stem":"「사」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"사","eq":false,"lay":"blank"},"options":[{"t":"ㅅ","correct":true},{"t":"ㅏ","mis":"K1-1-u1-X01"},{"t":"ㅈ","mis":"K1-1-u1-X04"}],"explanation":["「사」는 자음자 ㅅ과 모음자 ㅏ가 만난 글자예요.","자음자는 ㅅ이에요 — 왼쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":1,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#5','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',2,'mc','auto','「포」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X02']::text[],true,'{"seq":5,"kind":"mc","stem":"「포」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"포","eq":false,"lay":"blank"},"options":[{"t":"ㅗ","correct":true},{"t":"ㅍ","mis":"K1-1-u1-X01"},{"t":"ㅜ","mis":"K1-1-u1-X02"}],"explanation":["「포」는 자음자 ㅍ과 모음자 ㅗ가 만난 글자예요.","모음자는 ㅗ예요 — 아래쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":2,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"mis":{"role":"X01","flip":"X02","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#6','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',2,'ox','auto','자음자 하나만 있어도 받침 없는 글자를 만들 수 있어요.',ARRAY['K1-1-u1-X01']::text[],true,'{"seq":6,"concept":"K1-1-u1-C1","difficulty":2,"kind":"ox","stem":"자음자 하나만 있어도 받침 없는 글자를 만들 수 있어요.","answer":"X","reason_options":[{"t":"받침 없는 글자는 자음자와 모음자가 만나야 하니까","correct":true},{"t":"자음자가 글자의 소리를 다 내니까","mis":"K1-1-u1-X01"}],"mis":"K1-1-u1-X01","explanation":["자음자 ㄱ만으로는 글자가 되지 않아요.","ㄱ에 모음자 ㅏ가 와야 「가」가 돼요.","글자 = 자음자 + 모음자."],"variant_rule":{"alt":[{"stem":"모음자 ㅏ 하나만 있으면 「가」를 만들 수 있어요.","answer":"X","reason_options":[{"t":"「가」에는 자음자 ㄱ도 있어야 하니까","correct":true},{"t":"모음자가 글자의 소리를 다 내니까","mis":"K1-1-u1-X01"}],"explanation":["「가」는 ㄱ과 ㅏ가 만난 글자예요.","모음자 하나로는 「가」가 되지 않아요.","글자 = 자음자 + 모음자."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#7','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C2',2,'mc','auto','ㄴ + ㅏ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":7,"kind":"mc","stem":"ㄴ + ㅏ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄴ","v":"ㅏ","s":null},"options":[{"t":"나","correct":true},{"t":"너","mis":"K1-1-u1-X02"},{"t":"냐","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㄴ과 모음자 ㅏ가 만나면 「나」예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#8','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C2',2,'match','auto','자음자와 모음자를 모아 만든 글자를 바르게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"K1-1-u1-C2","difficulty":2,"kind":"match","stem":"자음자와 모음자를 모아 만든 글자를 바르게 이으세요.","pairs":[{"l":"ㄱ + ㅏ","r":"가"},{"l":"ㄱ + ㅣ","r":"기"},{"l":"ㄱ + ㅗ","r":"고"}],"mis":"K1-1-u1-X08","explanation":["자음자는 모두 ㄱ이에요.","모음자가 ㅏ·ㅣ·ㅗ로 달라서 글자가 달라요.","모음자까지 보고 이어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 자음자와 모음자를 모아 만든 글자를 바르게 이으세요.","pairs":[{"l":"ㅁ + ㅏ","r":"마"},{"l":"ㅁ + ㅜ","r":"무"},{"l":"ㅁ + ㅣ","r":"미"}],"explanation":["자음자는 모두 ㅁ이에요.","모음자가 달라서 글자가 달라요.","모음자까지 보고 이어요."]},{"stem":"이번에는 다른 보기예요. 자음자와 모음자를 모아 만든 글자를 바르게 이으세요.","pairs":[{"l":"ㄴ + ㅓ","r":"너"},{"l":"ㄴ + ㅗ","r":"노"},{"l":"ㄴ + ㅏ","r":"나"}],"explanation":["자음자는 모두 ㄴ이에요.","모음자가 달라서 글자가 달라요.","모음자까지 보고 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#9','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C1',2,'mc','auto','모음자끼리만 모은 것은 어느 것인가요?',ARRAY['K1-1-u1-X01']::text[],true,'{"seq":9,"concept":"K1-1-u1-C1","difficulty":2,"kind":"mc","stem":"모음자끼리만 모은 것은 어느 것인가요?","options":[{"t":"ㅏ · ㅗ · ㅣ","correct":true},{"t":"ㅏ · ㄱ · ㅣ","mis":"K1-1-u1-X01"},{"t":"ㄴ · ㄷ · ㅁ","mis":"K1-1-u1-X01"}],"explanation":["ㅏ·ㅗ·ㅣ는 모두 모음자예요.","ㄱ은 자음자라 섞이면 안 되고, ㄴ·ㄷ·ㅁ은 모두 자음자예요.","하나씩 짚어 가며 골라요."],"variant_rule":{"alt":[{"stem":"자음자끼리만 모은 것은 어느 것인가요?","options":[{"t":"ㄹ · ㅅ · ㅎ","correct":true},{"t":"ㄹ · ㅓ · ㅎ","mis":"K1-1-u1-X01"},{"t":"ㅑ · ㅜ · ㅡ","mis":"K1-1-u1-X01"}],"explanation":["ㄹ·ㅅ·ㅎ은 모두 자음자예요.","ㅓ는 모음자라 섞이면 안 되고, ㅑ·ㅜ·ㅡ는 모두 모음자예요.","하나씩 짚어 가며 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_basic#10','kor',1,1,'u1','L01','g1_1_kor_u1_L01_basic','lesson_basic','K1-1-u1-C2',3,'mc','auto','「무」를 만들려면 어떤 두 카드가 있어야 할까요?',ARRAY['K1-1-u1-X02','K1-1-u1-X04']::text[],true,'{"seq":10,"concept":"K1-1-u1-C2","difficulty":3,"kind":"mc","stem":"「무」를 만들려면 어떤 두 카드가 있어야 할까요?","options":[{"t":"ㅁ과 ㅜ","correct":true},{"t":"ㅁ과 ㅗ","mis":"K1-1-u1-X02"},{"t":"ㅂ과 ㅜ","mis":"K1-1-u1-X04"}],"explanation":["「무」는 자음자 ㅁ과 모음자 ㅜ가 만난 글자예요.","ㅗ면 「모」, ㅂ이면 「부」가 돼요.","자음자 하나 + 모음자 하나."],"variant_rule":{"alt":[{"stem":"「도」를 만들려면 어떤 두 카드가 있어야 할까요?","options":[{"t":"ㄷ과 ㅗ","correct":true},{"t":"ㄷ과 ㅜ","mis":"K1-1-u1-X02"},{"t":"ㅌ과 ㅗ","mis":"K1-1-u1-X04"}],"explanation":["「도」는 ㄷ과 ㅗ가 만난 글자예요.","ㅜ면 「두」, ㅌ이면 「토」가 돼요.","자음자 하나 + 모음자 하나."]},{"stem":"「거」를 만들려면 어떤 두 카드가 있어야 할까요?","options":[{"t":"ㄱ과 ㅓ","correct":true},{"t":"ㄱ과 ㅏ","mis":"K1-1-u1-X02"},{"t":"ㅋ과 ㅓ","mis":"K1-1-u1-X04"}],"explanation":["「거」는 ㄱ과 ㅓ가 만난 글자예요.","ㅏ면 「가」, ㅋ이면 「커」가 돼요.","자음자 하나 + 모음자 하나."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#1','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C1',2,'mc','auto','자음자와 모음자를 바르게 나눈 것은 어느 것인가요?',ARRAY['K1-1-u1-X01']::text[],false,'{"seq":1,"concept":"K1-1-u1-C1","difficulty":2,"kind":"mc","stem":"자음자와 모음자를 바르게 나눈 것은 어느 것인가요?","options":[{"t":"자음자 ㄹ · 모음자 ㅑ","correct":true},{"t":"자음자 ㅕ · 모음자 ㅅ","mis":"K1-1-u1-X01"},{"t":"자음자 ㅗ · 모음자 ㅁ","mis":"K1-1-u1-X01"}],"explanation":["ㄹ은 자음자, ㅑ는 모음자예요.","ㅕ·ㅗ는 모음자, ㅅ·ㅁ은 자음자라 자리가 바뀌었어요.","파랑은 자음자, 주황은 모음자."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#2','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C2',2,'mc','auto','자음자 ㄷ과 모음자 ㅗ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X06']::text[],true,'{"seq":2,"kind":"mc","stem":"자음자 ㄷ과 모음자 ㅗ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄷ","v":"ㅗ","s":null,"lay":true},"options":[{"t":"도","correct":true},{"t":"두","mis":"K1-1-u1-X02"},{"t":"다","mis":"K1-1-u1-X06"}],"explanation":["자음자 ㄷ과 모음자 ㅗ가 만나면 「도」예요.","ㅗ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄷ","ㄱ","ㅂ","ㅈ","ㄴ"],"vows":["ㅗ","ㅜ","ㅏ","ㅓ"],"mis":{"flip":"X02","rot":"X06","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#3','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C1',3,'mc','auto','「겨」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X02']::text[],true,'{"seq":3,"kind":"mc","stem":"「겨」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"겨","eq":false,"lay":"blank"},"options":[{"t":"ㅕ","correct":true},{"t":"ㄱ","mis":"K1-1-u1-X01"},{"t":"ㅑ","mis":"K1-1-u1-X02"}],"explanation":["「겨」는 자음자 ㄱ과 모음자 ㅕ가 만난 글자예요.","모음자는 ㅕ예요 — 오른쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":3,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㄴ","ㅁ","ㅅ","ㅇ","ㅎ"],"vows":["ㅑ","ㅕ","ㅛ","ㅠ"],"mis":{"role":"X01","flip":"X02","stroke":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#4','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C2',3,'error','auto','윤호가 자음자 ㅎ과 모음자 ㅏ를 모아 「아」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X04','K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":4,"concept":"K1-1-u1-C2","difficulty":3,"kind":"error","stem":"윤호가 자음자 ㅎ과 모음자 ㅏ를 모아 「아」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자를 ㅇ으로 바꾸어 썼어요 — ㅎ과 ㅏ는 「하」예요","correct":true,"mis_target":"K1-1-u1-X04"},{"t":"모음자를 잘못 썼어요 — ㅎ과 ㅏ는 「허」예요","mis":"K1-1-u1-X02"},{"t":"짧은 획이 하나 모자라요 — ㅎ과 ㅏ는 「햐」예요","mis":"K1-1-u1-X03"}],"explanation":["ㅎ과 ㅇ은 닮았지만 다른 자음자예요.","ㅎ + ㅏ = 하, ㅇ + ㅏ = 아.","자음자 모양을 꼼꼼히 견주어요."],"variant_rule":{"alt":[{"stem":"서아가 자음자 ㄷ과 모음자 ㅗ를 모아 「토」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자를 ㅌ으로 바꾸어 썼어요 — ㄷ과 ㅗ는 「도」예요","correct":true,"mis_target":"K1-1-u1-X04"},{"t":"모음자를 잘못 썼어요 — ㄷ과 ㅗ는 「두」예요","mis":"K1-1-u1-X02"},{"t":"짧은 획이 하나 모자라요 — ㄷ과 ㅗ는 「됴」예요","mis":"K1-1-u1-X03"}],"explanation":["ㄷ과 ㅌ은 닮았지만 다른 자음자예요.","ㄷ + ㅗ = 도, ㅌ + ㅗ = 토.","자음자 모양을 꼼꼼히 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#5','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C1',3,'mc','auto','「가 · 나 · 다」에 모두 들어 있는 것은 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X02']::text[],true,'{"seq":5,"concept":"K1-1-u1-C1","difficulty":3,"kind":"mc","stem":"「가 · 나 · 다」에 모두 들어 있는 것은 어느 것인가요?","options":[{"t":"모음자 ㅏ","correct":true},{"t":"자음자 ㄱ","mis":"K1-1-u1-X01"},{"t":"모음자 ㅓ","mis":"K1-1-u1-X02"}],"explanation":["세 글자 모두 오른쪽에 ㅏ가 있어요.","ㄱ은 「가」에만 있고, ㅓ는 없어요.","같은 자리를 견주어 봐요."],"variant_rule":{"alt":[{"stem":"「고 · 노 · 도」에 모두 들어 있는 것은 어느 것인가요?","options":[{"t":"모음자 ㅗ","correct":true},{"t":"자음자 ㄴ","mis":"K1-1-u1-X01"},{"t":"모음자 ㅜ","mis":"K1-1-u1-X02"}],"explanation":["세 글자 모두 아래에 ㅗ가 있어요.","ㄴ은 「노」에만 있고, ㅜ는 없어요.","같은 자리를 견주어 봐요."]},{"stem":"「기 · 미 · 시」에 모두 들어 있는 것은 어느 것인가요?","options":[{"t":"모음자 ㅣ","correct":true},{"t":"자음자 ㅁ","mis":"K1-1-u1-X01"},{"t":"모음자 ㅡ","mis":"K1-1-u1-X06"}],"explanation":["세 글자 모두 오른쪽에 ㅣ가 있어요.","ㅁ은 「미」에만 있고, ㅡ는 없어요.","같은 자리를 견주어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#6','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C2',3,'sa','auto','자음자 ㅈ과 모음자 ㅓ가 만나면 어떤 글자가 되나요?','{}'::text[],true,'{"seq":6,"kind":"sa","stem":"자음자 ㅈ과 모음자 ㅓ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅈ","v":"ㅓ","s":null},"answer":["저"],"explanation":["자음자 ㅈ과 모음자 ㅓ가 만나면 「저」예요.","ㅓ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#7','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C1',3,'ox','auto','「오」는 모음자 ㅗ 하나로만 된 글자예요.',ARRAY['K1-1-u1-X16']::text[],true,'{"seq":7,"concept":"K1-1-u1-C1","difficulty":3,"kind":"ox","stem":"「오」는 모음자 ㅗ 하나로만 된 글자예요.","answer":"X","reason_options":[{"t":"「오」는 위에 자음자 ㅇ, 아래에 모음자 ㅗ가 있으니까","correct":true},{"t":"ㅇ은 소리가 없어서 자음자가 아니니까","mis":"K1-1-u1-X16"}],"mis":"K1-1-u1-X16","explanation":["「오」에도 자음자 ㅇ이 있어요.","ㅇ은 소리가 나지 않지만 자음자 자리를 채워요.","아·오·이도 자음자 + 모음자."],"variant_rule":{"alt":[{"stem":"「이」는 모음자 ㅣ 하나로만 된 글자예요.","answer":"X","reason_options":[{"t":"「이」는 왼쪽에 자음자 ㅇ, 오른쪽에 모음자 ㅣ가 있으니까","correct":true},{"t":"ㅇ은 소리가 없어서 자음자가 아니니까","mis":"K1-1-u1-X16"}],"explanation":["「이」에도 자음자 ㅇ이 있어요.","ㅇ은 소리가 나지 않지만 자음자 자리를 채워요.","아·오·이도 자음자 + 모음자."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#8','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C2',4,'mc','auto','같은 자음자에 모음자만 바꾸어 만든 글자끼리 모은 것은 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":8,"concept":"K1-1-u1-C2","difficulty":4,"kind":"mc","stem":"같은 자음자에 모음자만 바꾸어 만든 글자끼리 모은 것은 어느 것인가요?","options":[{"t":"가 · 고 · 기","correct":true},{"t":"가 · 나 · 다","mis":"K1-1-u1-X01"},{"t":"가 · 거 · 카","mis":"K1-1-u1-X04"}],"explanation":["「가·고·기」는 모두 ㄱ에 모음자만 달라요.","「가·나·다」는 모음자가 같고 자음자가 달라요. 「카」는 자음자가 ㅋ이에요.","무엇이 같고 무엇이 바뀌었나 견주어요."],"variant_rule":{"alt":[{"stem":"같은 모음자에 자음자만 바꾸어 만든 글자끼리 모은 것은 어느 것인가요?","options":[{"t":"노 · 도 · 로","correct":true},{"t":"노 · 너 · 나","mis":"K1-1-u1-X01"},{"t":"노 · 도 · 두","mis":"K1-1-u1-X02"}],"explanation":["「노·도·로」는 모두 ㅗ에 자음자만 달라요.","「노·너·나」는 자음자가 같고 모음자가 달라요. 「두」는 모음자가 ㅜ예요.","무엇이 같고 무엇이 바뀌었나 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#9','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C1',4,'essay','teacher','「바다」를 자음자와 모음자로 나누어 보고, 어떻게 나누었는지 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u1-C1","difficulty":4,"kind":"essay","stem":"「바다」를 자음자와 모음자로 나누어 보고, 어떻게 나누었는지 말해 보세요.","answer_guide":{"answer":"예: 「바」는 자음자 ㅂ과 모음자 ㅏ, 「다」는 자음자 ㄷ과 모음자 ㅏ로 나누었어요. 글자마다 파란 자음자 하나, 주황 모음자 하나를 찾았어요. — 두 글자를 다 나누고 자음자·모음자 이름을 바르게 말하면 맞아요.","scoring_points":["「바」를 ㅂ과 ㅏ로 나누었는가","「다」를 ㄷ과 ㅏ로 나누었는가","글자마다 자음자 하나·모음자 하나라는 방법을 말했는가"]},"explanation":["바 = ㅂ + ㅏ.","다 = ㄷ + ㅏ.","글자마다 자음자 하나, 모음자 하나."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L01_challenge#10','kor',1,1,'u1','L01','g1_1_kor_u1_L01_challenge','lesson_challenge','K1-1-u1-C2',4,'mc','auto','카드 ㄴ · ㅁ · ㅏ · ㅗ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?',ARRAY['K1-1-u1-X02']::text[],true,'{"seq":10,"concept":"K1-1-u1-C2","difficulty":4,"kind":"mc","stem":"카드 ㄴ · ㅁ · ㅏ · ㅗ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?","options":[{"t":"누","correct":true},{"t":"노","mis":"K1-1-u1-X02"},{"t":"모","mis":"K1-1-u1-X02"}],"explanation":["「누」에는 ㅜ가 있어야 하는데 카드에 ㅜ가 없어요.","「노」는 ㄴ+ㅗ, 「모」는 ㅁ+ㅗ로 만들 수 있어요.","ㅗ와 ㅜ는 방향이 달라요."],"variant_rule":{"alt":[{"stem":"카드 ㄱ · ㅅ · ㅓ · ㅣ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"거","mis":"K1-1-u1-X02"},{"t":"시","mis":"K1-1-u1-X01"}],"explanation":["「가」에는 ㅏ가 있어야 하는데 카드에 ㅏ가 없어요.","「거」는 ㄱ+ㅓ, 「시」는 ㅅ+ㅣ로 만들 수 있어요.","ㅏ와 ㅓ는 방향이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#1','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C1',1,'mc','auto','「가」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":1,"kind":"mc","stem":"「가」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"가","eq":false,"lay":"blank"},"options":[{"t":"ㄱ","correct":true},{"t":"ㅏ","mis":"K1-1-u1-X01"},{"t":"ㅋ","mis":"K1-1-u1-X04"}],"explanation":["「가」는 자음자 ㄱ과 모음자 ㅏ가 만난 글자예요.","자음자는 ㄱ이에요 — 왼쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":1,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#2','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C1',1,'mc','auto','「이」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X06']::text[],true,'{"seq":2,"kind":"mc","stem":"「이」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"이","eq":false,"lay":"blank"},"options":[{"t":"ㅣ","correct":true},{"t":"ㅇ","mis":"K1-1-u1-X01"},{"t":"ㅡ","mis":"K1-1-u1-X06"}],"explanation":["「이」는 자음자 ㅇ과 모음자 ㅣ가 만난 글자예요.","모음자는 ㅣ예요 — 오른쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":1,"variant_rule":{"jamo":{"ask":"vow","cons":["ㅇ","ㄱ","ㄴ","ㅁ","ㅅ"],"vows":["ㅣ","ㅡ","ㅏ","ㅗ"],"mis":{"role":"X01","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#3','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C3',1,'mc','auto','「고」에서 자음자 ㄱ은 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":3,"kind":"mc","stem":"「고」에서 자음자 ㄱ은 어디에 있나요?","asset":{"type":"jamo","s":"고","eq":false},"options":[{"t":"위쪽","correct":true},{"t":"왼쪽","mis":"K1-1-u1-X05"},{"t":"아래쪽","mis":"K1-1-u1-X01"}],"explanation":["「고」는 위아래로 쌓아서 만든 글자예요.","ㅗ는 가로로 길어서 자음자 아래에 쌓여요.","그래서 자음자 ㄱ은 위쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":1,"variant_rule":{"jamo":{"ask":"place","role":"c","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#4','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C3',1,'mc','auto','「파」에서 모음자 ㅏ는 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":4,"kind":"mc","stem":"「파」에서 모음자 ㅏ는 어디에 있나요?","asset":{"type":"jamo","s":"파","eq":false},"options":[{"t":"오른쪽","correct":true},{"t":"아래쪽","mis":"K1-1-u1-X05"},{"t":"왼쪽","mis":"K1-1-u1-X01"}],"explanation":["「파」는 옆으로 나란히 만든 글자예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","그래서 모음자 ㅏ는 오른쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":1,"variant_rule":{"jamo":{"ask":"place","role":"v","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#5','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C2',2,'mc','auto','자음자 ㅁ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":5,"kind":"mc","stem":"자음자 ㅁ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅁ","v":"ㅏ","s":null,"lay":true},"options":[{"t":"마","correct":true},{"t":"머","mis":"K1-1-u1-X02"},{"t":"먀","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅁ과 모음자 ㅏ가 만나면 「마」예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅣ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#6','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C2',2,'mc','auto','자음자 ㅁ과 모음자 ㅜ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":6,"kind":"mc","stem":"자음자 ㅁ과 모음자 ㅜ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅁ","v":"ㅜ","s":null,"lay":true},"options":[{"t":"무","correct":true},{"t":"모","mis":"K1-1-u1-X02"},{"t":"뮤","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅁ과 모음자 ㅜ가 만나면 「무」예요.","ㅜ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅗ","ㅜ"],"mis":{"flip":"X02","stroke":"X03","rot":"X06"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#7','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C3',2,'mc','auto','옆으로 나란히 만든 글자는 어느 것인가요?',ARRAY['K1-1-u1-X05']::text[],true,'{"seq":7,"concept":"K1-1-u1-C3","difficulty":2,"kind":"mc","stem":"옆으로 나란히 만든 글자는 어느 것인가요?","options":[{"t":"거","correct":true},{"t":"구","mis":"K1-1-u1-X05"},{"t":"그","mis":"K1-1-u1-X05"}],"explanation":["「거」는 ㄱ 오른쪽에 ㅓ가 나란히 있어요.","「구」·「그」는 ㄱ 아래에 모음자가 쌓였어요.","세로로 긴 모음자는 옆에."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 옆으로 나란히 만든 글자는 어느 것인가요?","options":[{"t":"미","correct":true},{"t":"무","mis":"K1-1-u1-X05"},{"t":"모","mis":"K1-1-u1-X05"}],"explanation":["「미」는 ㅁ 오른쪽에 ㅣ가 있어요.","「무」·「모」는 ㅁ 아래에 모음자가 쌓였어요.","세로로 긴 모음자는 옆에."]},{"stem":"이번에는 다른 보기예요. 옆으로 나란히 만든 글자는 어느 것인가요?","options":[{"t":"서","correct":true},{"t":"수","mis":"K1-1-u1-X05"},{"t":"소","mis":"K1-1-u1-X05"}],"explanation":["「서」는 ㅅ 오른쪽에 ㅓ가 있어요.","「수」·「소」는 ㅅ 아래에 모음자가 쌓였어요.","세로로 긴 모음자는 옆에."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#8','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C1',2,'mc','auto','「지」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":8,"kind":"mc","stem":"「지」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"지","eq":false,"lay":"blank"},"options":[{"t":"ㅈ","correct":true},{"t":"ㅣ","mis":"K1-1-u1-X01"},{"t":"ㅊ","mis":"K1-1-u1-X04"}],"explanation":["「지」는 자음자 ㅈ과 모음자 ㅣ가 만난 글자예요.","자음자는 ㅈ이에요 — 왼쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":2,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#9','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C3',2,'ox','auto','「오」를 둘로 나누면 ㅇ이 위에, ㅗ가 아래에 있어요.',ARRAY['K1-1-u1-X16']::text[],true,'{"seq":9,"concept":"K1-1-u1-C3","difficulty":2,"kind":"ox","stem":"「오」를 둘로 나누면 ㅇ이 위에, ㅗ가 아래에 있어요.","answer":"O","reason_options":[{"t":"ㅗ는 가로로 길어서 자음자 아래에 쌓이니까","correct":true},{"t":"ㅇ은 소리가 없어서 아무 데나 써도 되니까","mis":"K1-1-u1-X16"}],"mis":"K1-1-u1-X05","explanation":["「오」는 위아래로 쌓은 글자예요.","ㅇ이 위, ㅗ가 아래.","소리 없는 ㅇ도 제자리가 있어요."],"variant_rule":{"alt":[{"stem":"「아」를 둘로 나누면 ㅇ이 위에, ㅏ가 아래에 있어요.","answer":"X","reason_options":[{"t":"ㅏ는 세로로 길어서 ㅇ 오른쪽에 나란히 서니까","correct":true},{"t":"ㅇ은 언제나 위에만 쓰니까","mis":"K1-1-u1-X05"}],"explanation":["「아」는 옆으로 나란히 만든 글자예요.","ㅇ이 왼쪽, ㅏ가 오른쪽.","모음자 모양을 보고 자리를 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_basic#10','kor',1,1,'u1','L03','g1_1_kor_u1_L03_basic','lesson_basic','K1-1-u1-C3',3,'mc','auto','「구」에서 모음자 ㅜ는 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":10,"kind":"mc","stem":"「구」에서 모음자 ㅜ는 어디에 있나요?","asset":{"type":"jamo","s":"구","eq":false},"options":[{"t":"아래쪽","correct":true},{"t":"오른쪽","mis":"K1-1-u1-X05"},{"t":"위쪽","mis":"K1-1-u1-X01"}],"explanation":["「구」는 위아래로 쌓아서 만든 글자예요.","ㅜ는 가로로 길어서 자음자 아래에 쌓여요.","그래서 모음자 ㅜ는 아래쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":3,"variant_rule":{"jamo":{"ask":"place","role":"v","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#1','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C3',2,'match','auto','모음자와 그 모음자가 서는 자리를 바르게 이으세요.','{}'::text[],true,'{"seq":1,"concept":"K1-1-u1-C3","difficulty":2,"kind":"match","stem":"모음자와 그 모음자가 서는 자리를 바르게 이으세요.","pairs":[{"l":"세로로 긴 ㅣ","r":"자음자 오른쪽"},{"l":"가로로 긴 ㅡ","r":"자음자 아래쪽"},{"l":"자음자 ㄱ","r":"글자의 맨 앞(왼쪽이나 위쪽)"}],"mis":"K1-1-u1-X05","explanation":["세로로 긴 모음자는 오른쪽에 서요.","가로로 긴 모음자는 아래에 쌓여요.","자음자는 언제나 먼저 와요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모음자와 그 모음자가 서는 자리를 바르게 이으세요.","pairs":[{"l":"세로로 긴 ㅓ","r":"자음자 오른쪽"},{"l":"가로로 긴 ㅜ","r":"자음자 아래쪽"},{"l":"자음자 ㅅ","r":"글자의 맨 앞(왼쪽이나 위쪽)"}],"explanation":["세로로 긴 모음자는 오른쪽에 서요.","가로로 긴 모음자는 아래에 쌓여요.","자음자는 언제나 먼저 와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#2','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C1',2,'mc','auto','「구」에서 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X02']::text[],true,'{"seq":2,"kind":"mc","stem":"「구」에서 모음자는 어느 것인가요?","asset":{"type":"jamo","s":"구","eq":false,"lay":"blank"},"options":[{"t":"ㅜ","correct":true},{"t":"ㄱ","mis":"K1-1-u1-X01"},{"t":"ㅗ","mis":"K1-1-u1-X02"}],"explanation":["「구」는 자음자 ㄱ과 모음자 ㅜ가 만난 글자예요.","모음자는 ㅜ예요 — 아래쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":2,"variant_rule":{"jamo":{"ask":"vow","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"mis":{"role":"X01","flip":"X02","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#3','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C3',3,'error','auto','민지가 「누」를 쓸 때 ㅜ를 ㄴ 오른쪽에 붙여 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X02','K1-1-u1-X04']::text[],true,'{"seq":3,"concept":"K1-1-u1-C3","difficulty":3,"kind":"error","stem":"민지가 「누」를 쓸 때 ㅜ를 ㄴ 오른쪽에 붙여 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅜ는 가로로 길어서 ㄴ 아래에 써야 해요","correct":true,"mis_target":"K1-1-u1-X05"},{"t":"ㅜ 대신 ㅗ를 써야 해요","mis":"K1-1-u1-X02"},{"t":"ㄴ 대신 ㄷ을 써야 해요","mis":"K1-1-u1-X04"}],"explanation":["ㅜ는 가로로 누운 모음자예요.","누운 모음자는 자음자 아래에 쌓아요.","ㄴ을 위에, ㅜ를 아래에."],"variant_rule":{"alt":[{"stem":"지호가 「바」를 쓸 때 ㅏ를 ㅂ 아래에 붙여 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅏ는 세로로 길어서 ㅂ 오른쪽에 써야 해요","correct":true,"mis_target":"K1-1-u1-X05"},{"t":"ㅏ 대신 ㅓ를 써야 해요","mis":"K1-1-u1-X02"},{"t":"ㅂ 대신 ㅍ을 써야 해요","mis":"K1-1-u1-X04"}],"explanation":["ㅏ는 세로로 선 모음자예요.","선 모음자는 자음자 오른쪽에 나란히.","ㅂ을 왼쪽에, ㅏ를 오른쪽에."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#4','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C1',3,'mc','auto','「토」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":4,"kind":"mc","stem":"「토」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"토","eq":false,"lay":"blank"},"options":[{"t":"ㅌ","correct":true},{"t":"ㅗ","mis":"K1-1-u1-X01"},{"t":"ㄷ","mis":"K1-1-u1-X04"}],"explanation":["「토」는 자음자 ㅌ과 모음자 ㅗ가 만난 글자예요.","자음자는 ㅌ이에요 — 위쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":3,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#5','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C3',3,'mc','auto','자음자가 위쪽에 있는 글자끼리 모은 것은 어느 것인가요?',ARRAY['K1-1-u1-X05']::text[],true,'{"seq":5,"concept":"K1-1-u1-C3","difficulty":3,"kind":"mc","stem":"자음자가 위쪽에 있는 글자끼리 모은 것은 어느 것인가요?","options":[{"t":"소 · 무 · 그","correct":true},{"t":"소 · 마 · 그","mis":"K1-1-u1-X05"},{"t":"사 · 머 · 기","mis":"K1-1-u1-X05"}],"explanation":["「소·무·그」는 모두 모음자가 아래에 쌓였어요.","「마·사·머·기」는 자음자가 왼쪽에 있어요.","가로로 긴 모음자를 찾아요."],"variant_rule":{"alt":[{"stem":"자음자가 왼쪽에 있는 글자끼리 모은 것은 어느 것인가요?","options":[{"t":"나 · 저 · 비","correct":true},{"t":"나 · 조 · 비","mis":"K1-1-u1-X05"},{"t":"노 · 주 · 브","mis":"K1-1-u1-X05"}],"explanation":["「나·저·비」는 모두 모음자가 오른쪽에 섰어요.","「조·노·주·브」는 자음자가 위쪽에 있어요.","세로로 긴 모음자를 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#6','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C2',3,'mc','auto','ㅅ + ㅗ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X06']::text[],true,'{"seq":6,"kind":"mc","stem":"ㅅ + ㅗ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅅ","v":"ㅗ","s":null},"options":[{"t":"소","correct":true},{"t":"수","mis":"K1-1-u1-X02"},{"t":"사","mis":"K1-1-u1-X06"}],"explanation":["자음자 ㅅ과 모음자 ㅗ가 만나면 「소」예요.","ㅗ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅗ","ㅜ","ㅏ","ㅓ"],"mis":{"flip":"X02","rot":"X06","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#7','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C3',3,'mc','auto','「너」에서 모음자 ㅓ는 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":7,"kind":"mc","stem":"「너」에서 모음자 ㅓ는 어디에 있나요?","asset":{"type":"jamo","s":"너","eq":false},"options":[{"t":"오른쪽","correct":true},{"t":"아래쪽","mis":"K1-1-u1-X05"},{"t":"왼쪽","mis":"K1-1-u1-X01"}],"explanation":["「너」는 옆으로 나란히 만든 글자예요.","ㅓ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","그래서 모음자 ㅓ는 오른쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":3,"variant_rule":{"jamo":{"ask":"place","role":"v","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#8','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C1',4,'mc','auto','「오이」의 두 글자에 똑같이 들어 있는 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X16']::text[],true,'{"seq":8,"concept":"K1-1-u1-C1","difficulty":4,"kind":"mc","stem":"「오이」의 두 글자에 똑같이 들어 있는 자음자는 어느 것인가요?","options":[{"t":"ㅇ","correct":true},{"t":"ㅗ","mis":"K1-1-u1-X01"},{"t":"없어요 — 「오」와 「이」는 모음자 하나로 된 글자예요","mis":"K1-1-u1-X16"}],"explanation":["「오」도 「이」도 자음자 ㅇ으로 시작해요.","ㅗ는 모음자예요. 소리가 없어도 ㅇ은 자음자예요.","아·오·이·우에도 ㅇ이 숨어 있어요."],"variant_rule":{"alt":[{"stem":"「아우」의 두 글자에 똑같이 들어 있는 자음자는 어느 것인가요?","options":[{"t":"ㅇ","correct":true},{"t":"ㅏ","mis":"K1-1-u1-X01"},{"t":"없어요 — 「아」와 「우」는 모음자 하나로 된 글자예요","mis":"K1-1-u1-X16"}],"explanation":["「아」도 「우」도 자음자 ㅇ으로 시작해요.","ㅏ는 모음자예요. 소리가 없어도 ㅇ은 자음자예요.","아·오·이·우에도 ㅇ이 숨어 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#9','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C3',4,'essay','teacher','「무」와 「마」는 자음자가 같아요. 그런데 두 글자의 모양이 왜 다를까요?','{}'::text[],false,'{"seq":9,"concept":"K1-1-u1-C3","difficulty":4,"kind":"essay","stem":"「무」와 「마」는 자음자가 같아요. 그런데 두 글자의 모양이 왜 다를까요?","answer_guide":{"answer":"예: 「마」의 ㅏ는 세로로 길어서 ㅁ 오른쪽에 서고, 「무」의 ㅜ는 가로로 길어서 ㅁ 아래에 쌓이기 때문이에요. — 모음자 모양(세로·가로)과 자리(오른쪽·아래)를 함께 말하면 맞아요.","scoring_points":["모음자가 ㅏ와 ㅜ로 다르다고 말했는가","ㅏ는 오른쪽, ㅜ는 아래에 온다고 말했는가","모음자가 세로로 긴지 가로로 긴지로 까닭을 댔는가"]},"explanation":["같은 ㅁ이라도 짝 모음자가 달라요.","ㅏ는 옆으로, ㅜ는 위아래로.","모음자 모양이 자리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L03_challenge#10','kor',1,1,'u1','L03','g1_1_kor_u1_L03_challenge','lesson_challenge','K1-1-u1-C1',4,'sa','auto','「포도」의 두 글자에 똑같이 들어 있는 모음자를 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"K1-1-u1-C1","difficulty":4,"kind":"sa","stem":"「포도」의 두 글자에 똑같이 들어 있는 모음자를 쓰세요.","answer":["ㅗ"],"explanation":["「포」와 「도」 모두 아래에 ㅗ가 있어요.","자음자는 ㅍ과 ㄷ으로 달라요.","같은 자리를 견주어요."],"variant_rule":{"alt":[{"stem":"「나라」의 두 글자에 똑같이 들어 있는 모음자를 쓰세요.","answer":["ㅏ"],"explanation":["「나」와 「라」 모두 오른쪽에 ㅏ가 있어요.","자음자는 ㄴ과 ㄹ로 달라요.","같은 자리를 견주어요."]},{"stem":"「우유」의 두 글자에 똑같이 들어 있는 자음자를 쓰세요.","answer":["ㅇ"],"explanation":["「우」와 「유」 모두 위에 ㅇ이 있어요.","모음자는 ㅜ와 ㅠ로 달라요.","소리 없는 ㅇ도 자음자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#1','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C3',1,'mc','auto','위아래로 쌓아서 만든 글자는 어느 것인가요?',ARRAY['K1-1-u1-X05']::text[],true,'{"seq":1,"concept":"K1-1-u1-C3","difficulty":1,"kind":"mc","stem":"위아래로 쌓아서 만든 글자는 어느 것인가요?","options":[{"t":"노","correct":true},{"t":"나","mis":"K1-1-u1-X05"},{"t":"니","mis":"K1-1-u1-X05"}],"explanation":["「노」는 ㄴ 아래에 ㅗ가 쌓였어요.","「나」·「니」는 옆으로 나란히 만든 글자예요.","가로로 긴 모음자는 아래에."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 위아래로 쌓아서 만든 글자는 어느 것인가요?","options":[{"t":"두","correct":true},{"t":"더","mis":"K1-1-u1-X05"},{"t":"디","mis":"K1-1-u1-X05"}],"explanation":["「두」는 ㄷ 아래에 ㅜ가 쌓였어요.","「더」·「디」는 옆으로 나란히 만든 글자예요.","가로로 긴 모음자는 아래에."]},{"stem":"이번에는 다른 보기예요. 위아래로 쌓아서 만든 글자는 어느 것인가요?","options":[{"t":"흐","correct":true},{"t":"하","mis":"K1-1-u1-X05"},{"t":"히","mis":"K1-1-u1-X05"}],"explanation":["「흐」는 ㅎ 아래에 ㅡ가 쌓였어요.","「하」·「히」는 옆으로 나란히 만든 글자예요.","가로로 긴 모음자는 아래에."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#2','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C4',1,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X06','K1-1-u1-X07']::text[],true,'{"seq":2,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄱ","ㄴ","ㄷ"],"vows":["ㅏ","ㅗ","ㅣ"],"q":[1,1]},"options":[{"t":"노","correct":true},{"t":"나","mis":"K1-1-u1-X06"},{"t":"니","mis":"K1-1-u1-X07"}],"explanation":["? 칸은 자음자 ㄴ 줄과 모음자 ㅗ 칸이 만나는 곳이에요.","ㄴ과 ㅗ가 만나면 「노」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":1,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅁ","ㅂ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"grid":"X07","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
