INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#6','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C3',2,'mc','auto','「누」에서 자음자 ㄴ은 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":6,"kind":"mc","stem":"「누」에서 자음자 ㄴ은 어디에 있나요?","asset":{"type":"jamo","s":"누","eq":false},"options":[{"t":"위쪽","correct":true},{"t":"왼쪽","mis":"K1-1-u1-X05"},{"t":"아래쪽","mis":"K1-1-u1-X01"}],"explanation":["「누」는 위아래로 쌓아서 만든 글자예요.","ㅜ는 가로로 길어서 자음자 아래에 쌓여요.","그래서 자음자 ㄴ은 위쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":2,"variant_rule":{"jamo":{"ask":"place","role":"c","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#7','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C7',2,'mc','auto','글자 「비」와 「누」를 차례대로 모으면 어떤 낱말이 될까요?',ARRAY['K1-1-u1-X09','K1-1-u1-X02']::text[],true,'{"seq":7,"concept":"K1-1-u1-C7","difficulty":2,"kind":"mc","stem":"글자 「비」와 「누」를 차례대로 모으면 어떤 낱말이 될까요?","options":[{"t":"비누","correct":true},{"t":"누비","mis":"K1-1-u1-X09"},{"t":"비나","mis":"K1-1-u1-X02"}],"explanation":["「비」 다음에 「누」 — 비누.","차례가 바뀌면 「누비」가 돼요.","왼쪽부터 차례대로 모아요."],"variant_rule":{"alt":[{"stem":"글자 「도」와 「토」와 「리」를 차례대로 모으면 어떤 낱말이 될까요?","options":[{"t":"도토리","correct":true},{"t":"토도리","mis":"K1-1-u1-X09"},{"t":"도터리","mis":"K1-1-u1-X02"}],"explanation":["도 → 토 → 리, 도토리.","차례가 바뀌면 다른 말이 돼요.","왼쪽부터 차례대로 모아요."]},{"stem":"글자 「기」와 「차」를 차례대로 모으면 어떤 낱말이 될까요?","options":[{"t":"기차","correct":true},{"t":"차기","mis":"K1-1-u1-X09"},{"t":"기초","mis":"K1-1-u1-X06"}],"explanation":["「기」 다음에 「차」 — 기차.","차례가 바뀌면 「차기」가 돼요.","왼쪽부터 차례대로 모아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#8','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C3',2,'ox','auto','같은 자음자 ㄱ이라도 짝이 되는 모음자에 따라 자리가 달라져요.',ARRAY['K1-1-u1-X05']::text[],true,'{"seq":8,"concept":"K1-1-u1-C3","difficulty":2,"kind":"ox","stem":"같은 자음자 ㄱ이라도 짝이 되는 모음자에 따라 자리가 달라져요.","answer":"O","reason_options":[{"t":"「가」는 옆으로, 「고」는 위아래로 만드니까","correct":true},{"t":"ㄱ은 언제나 왼쪽에만 쓰니까","mis":"K1-1-u1-X05"}],"mis":"K1-1-u1-X05","explanation":["가: ㄱ이 왼쪽.","고: ㄱ이 위쪽.","모음자 모양이 자리를 정해요."],"variant_rule":{"alt":[{"stem":"같은 모음자 ㅏ라도 짝이 되는 자음자에 따라 자리가 달라져요.","answer":"X","reason_options":[{"t":"ㅏ는 어떤 자음자와 만나도 오른쪽에 서니까","correct":true},{"t":"자음자가 크면 ㅏ가 아래로 가니까","mis":"K1-1-u1-X05"}],"explanation":["가·나·다·마 모두 ㅏ가 오른쪽.","자리는 모음자 모양으로 정해져요.","세로로 긴 모음자는 늘 오른쪽."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#9','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C4',2,'mc','auto','음절표에서 ㄷ 줄을 따라 차례대로 읽은 것은 어느 것인가요?',ARRAY['K1-1-u1-X07','K1-1-u1-X02']::text[],true,'{"seq":9,"concept":"K1-1-u1-C4","difficulty":2,"kind":"mc","stem":"음절표에서 ㄷ 줄을 따라 차례대로 읽은 것은 어느 것인가요?","options":[{"t":"다 · 더 · 도 · 두","correct":true},{"t":"가 · 다 · 마","mis":"K1-1-u1-X07"},{"t":"다 · 더 · 두 · 도","mis":"K1-1-u1-X02"}],"explanation":["ㄷ 줄은 다·더·도·두예요.","「가·다·마」는 ㅏ 칸을 위에서 아래로 읽은 거예요.","줄은 옆으로 읽어요."],"asset":{"type":"syl_table","cons":["ㄱ","ㄷ","ㅁ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"]},"variant_rule":{"alt":[{"stem":"음절표에서 ㅁ 줄을 따라 차례대로 읽은 것은 어느 것인가요?","options":[{"t":"마 · 머 · 모 · 무","correct":true},{"t":"가 · 다 · 마","mis":"K1-1-u1-X07"},{"t":"마 · 머 · 무 · 모","mis":"K1-1-u1-X02"}],"explanation":["ㅁ 줄은 마·머·모·무예요.","「가·다·마」는 ㅏ 칸을 위에서 아래로 읽은 거예요.","줄은 옆으로 읽어요."],"asset":{"type":"syl_table","cons":["ㄱ","ㄷ","ㅁ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_basic#10','kor',1,1,'u1','L05','g1_1_kor_u1_L05_basic','lesson_basic','K1-1-u1-C4',3,'sa','auto','음절표에서 ? 칸에 들어갈 글자를 쓰세요.','{}'::text[],true,'{"seq":10,"kind":"sa","stem":"음절표에서 ? 칸에 들어갈 글자를 쓰세요.","asset":{"type":"syl_table","cons":["ㅅ","ㅈ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"q":[1,1]},"answer":["저"],"explanation":["? 칸은 자음자 ㅈ 줄과 모음자 ㅓ 칸이 만나는 곳이에요.","ㅈ과 ㅓ가 만나면 「저」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":3,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅁ","ㅂ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"grid":"X07","flip":"X02"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
