INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#2','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C4',2,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X02','K1-1-u1-X06']::text[],true,'{"seq":2,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄴ","ㅂ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"q":[1,3]},"options":[{"t":"부","correct":true},{"t":"보","mis":"K1-1-u1-X02"},{"t":"버","mis":"K1-1-u1-X06"}],"explanation":["? 칸은 자음자 ㅂ 줄과 모음자 ㅜ 칸이 만나는 곳이에요.","ㅂ과 ㅜ가 만나면 「부」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":2,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅁ","ㅂ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"grid":"X07","flip":"X02","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#3','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C3',3,'mc','auto','ㄱ에 어떤 모음자를 붙이면 위아래로 쌓은 글자가 될까요?',ARRAY['K1-1-u1-X05']::text[],true,'{"seq":3,"concept":"K1-1-u1-C3","difficulty":3,"kind":"mc","stem":"ㄱ에 어떤 모음자를 붙이면 위아래로 쌓은 글자가 될까요?","options":[{"t":"ㅠ","correct":true},{"t":"ㅕ","mis":"K1-1-u1-X05"},{"t":"ㅣ","mis":"K1-1-u1-X05"}],"explanation":["ㅠ는 가로로 길어서 ㄱ 아래에 쌓여요 — 규.","ㅕ·ㅣ는 세로로 길어서 옆에 서요.","가로로 긴 모음자를 찾아요."],"variant_rule":{"alt":[{"stem":"ㅅ에 어떤 모음자를 붙이면 옆으로 나란한 글자가 될까요?","options":[{"t":"ㅑ","correct":true},{"t":"ㅛ","mis":"K1-1-u1-X05"},{"t":"ㅡ","mis":"K1-1-u1-X05"}],"explanation":["ㅑ는 세로로 길어서 ㅅ 오른쪽에 서요 — 샤.","ㅛ·ㅡ는 가로로 길어서 아래에 쌓여요.","세로로 긴 모음자를 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#4','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C4',3,'error','auto','음절표의 ㅁ 줄 ㅗ 칸에 「노」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X07','K1-1-u1-X02','K1-1-u1-X06']::text[],true,'{"seq":4,"concept":"K1-1-u1-C4","difficulty":3,"kind":"error","stem":"음절표의 ㅁ 줄 ㅗ 칸에 「노」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자 줄을 잘못 보았어요 — ㅁ 줄이면 「모」예요","correct":true,"mis_target":"K1-1-u1-X07"},{"t":"모음자 칸을 잘못 보았어요 — ㅗ 칸이면 「무」예요","mis":"K1-1-u1-X02"},{"t":"카드를 돌려 보았어요 — 「마」라고 써야 해요","mis":"K1-1-u1-X06"}],"explanation":["ㅁ 줄과 ㅗ 칸이 만나면 「모」예요.","「노」는 ㄴ 줄의 글자예요.","줄은 자음자, 칸은 모음자."],"asset":{"type":"syl_table","cons":["ㄴ","ㅁ","ㅅ"],"vows":["ㅏ","ㅗ","ㅣ"]},"variant_rule":{"alt":[{"stem":"음절표의 ㅅ 줄 ㅣ 칸에 「니」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자 줄을 잘못 보았어요 — ㅅ 줄이면 「시」예요","correct":true,"mis_target":"K1-1-u1-X07"},{"t":"모음자 칸을 잘못 보았어요 — ㅣ 칸이면 「사」예요","mis":"K1-1-u1-X06"},{"t":"닮은 자음자를 썼어요 — 「지」라고 써야 해요","mis":"K1-1-u1-X04"}],"explanation":["ㅅ 줄과 ㅣ 칸이 만나면 「시」예요.","「니」는 ㄴ 줄의 글자예요.","줄은 자음자, 칸은 모음자."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#5','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C2',3,'mc','auto','ㅌ + ㅗ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X06']::text[],true,'{"seq":5,"kind":"mc","stem":"ㅌ + ㅗ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅌ","v":"ㅗ","s":null},"options":[{"t":"토","correct":true},{"t":"투","mis":"K1-1-u1-X02"},{"t":"타","mis":"K1-1-u1-X06"}],"explanation":["자음자 ㅌ과 모음자 ㅗ가 만나면 「토」예요.","ㅗ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㅌ","ㄷ","ㅋ","ㄱ","ㅍ","ㅂ"],"vows":["ㅗ","ㅜ","ㅏ","ㅓ"],"mis":{"flip":"X02","rot":"X06","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#6','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C7',3,'mc','auto','카드 「다」, 「리」, 「도」 가운데 두 장을 모아 몸의 한 부분을 나타내는 낱말을 만들면 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X15']::text[],true,'{"seq":6,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"카드 「다」, 「리」, 「도」 가운데 두 장을 모아 몸의 한 부분을 나타내는 낱말을 만들면 어느 것인가요?","options":[{"t":"다리","correct":true},{"t":"리다","mis":"K1-1-u1-X09"},{"t":"도리","mis":"K1-1-u1-X15"}],"explanation":["「다」 다음에 「리」 — 다리.","「리다」는 차례가 바뀌었고, 「도리」는 몸의 한 부분이 아니에요.","뜻을 생각하며 차례대로."],"asset":{"type":"scene","icon":"🦵"},"variant_rule":{"alt":[{"stem":"카드 「머」, 「리」, 「미」 가운데 두 장을 모아 몸의 한 부분을 나타내는 낱말을 만들면 어느 것인가요?","options":[{"t":"머리","correct":true},{"t":"리머","mis":"K1-1-u1-X09"},{"t":"미리","mis":"K1-1-u1-X15"}],"explanation":["「머」 다음에 「리」 — 머리.","「리머」는 차례가 바뀌었고, 「미리」는 몸의 한 부분이 아니에요.","뜻을 생각하며 차례대로."],"asset":{"type":"scene","icon":"🙆"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#7','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C3',3,'match','auto','글자와 그 글자의 짜임을 바르게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"K1-1-u1-C3","difficulty":3,"kind":"match","stem":"글자와 그 글자의 짜임을 바르게 이으세요.","pairs":[{"l":"바","r":"ㅂ 오른쪽에 ㅏ"},{"l":"부","r":"ㅂ 아래쪽에 ㅜ"},{"l":"비","r":"ㅂ 오른쪽에 ㅣ"}],"mis":"K1-1-u1-X05","explanation":["ㅏ·ㅣ는 오른쪽에 서요.","ㅜ는 아래에 쌓여요.","모음자 모양을 보고 이어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글자와 그 글자의 짜임을 바르게 이으세요.","pairs":[{"l":"소","r":"ㅅ 아래쪽에 ㅗ"},{"l":"서","r":"ㅅ 오른쪽에 ㅓ"},{"l":"스","r":"ㅅ 아래쪽에 ㅡ"}],"explanation":["ㅗ·ㅡ는 아래에 쌓여요.","ㅓ는 오른쪽에 서요.","모음자 모양을 보고 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#8','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C4',4,'mc','auto','이 음절표에서 「소」가 들어갈 칸을 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X07']::text[],true,'{"seq":8,"concept":"K1-1-u1-C4","difficulty":4,"kind":"mc","stem":"이 음절표에서 「소」가 들어갈 칸을 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"ㅅ 줄을 따라가다 ㅗ 칸에서 멈춰요","correct":true},{"t":"ㅗ 줄을 따라가다 ㅅ 칸에서 멈춰요","mis":"K1-1-u1-X01"},{"t":"ㅅ 줄 바로 옆 칸이면 아무 칸이나 돼요","mis":"K1-1-u1-X07"}],"explanation":["줄은 자음자 ㅅ, 칸은 모음자 ㅗ예요.","두 곳이 만나는 칸이 「소」예요.","줄 따라, 칸에서 멈추기."],"asset":{"type":"syl_table","cons":["ㄴ","ㄹ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ"]},"variant_rule":{"alt":[{"stem":"이 음절표에서 「러」가 들어갈 칸을 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"ㄹ 줄을 따라가다 ㅓ 칸에서 멈춰요","correct":true},{"t":"ㅓ 줄을 따라가다 ㄹ 칸에서 멈춰요","mis":"K1-1-u1-X01"},{"t":"ㄹ 줄 바로 옆 칸이면 아무 칸이나 돼요","mis":"K1-1-u1-X07"}],"explanation":["줄은 자음자 ㄹ, 칸은 모음자 ㅓ예요.","두 곳이 만나는 칸이 「러」예요.","줄 따라, 칸에서 멈추기."],"asset":{"type":"syl_table","cons":["ㄴ","ㄹ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#9','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C3',4,'essay','teacher','「소」를 공책에 쓸 때 ㅅ과 ㅗ를 어디에, 어떤 차례로 쓰는지 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u1-C3","difficulty":4,"kind":"essay","stem":"「소」를 공책에 쓸 때 ㅅ과 ㅗ를 어디에, 어떤 차례로 쓰는지 말해 보세요.","answer_guide":{"answer":"예: 먼저 자음자 ㅅ을 칸의 위쪽에 쓰고, 그 아래에 모음자 ㅗ를 써요. ㅗ는 가로로 길어서 ㅅ 아래에 쌓아요. — 자음자 먼저·위쪽, 모음자 나중·아래쪽을 말하면 맞아요.","scoring_points":["ㅅ을 먼저 쓴다고 말했는가","ㅅ은 위쪽, ㅗ는 아래쪽이라고 말했는가","ㅗ가 가로로 길어서 아래에 온다는 까닭을 댔는가"]},"explanation":["자음자 ㅅ을 먼저.","ㅗ는 ㅅ 아래에.","가로로 긴 모음자는 아래에 쌓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L05_challenge#10','kor',1,1,'u1','L05','g1_1_kor_u1_L05_challenge','lesson_challenge','K1-1-u1-C4',4,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":10,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄱ","ㄹ","ㅂ","ㅍ"],"vows":["ㅓ","ㅗ","ㅜ","ㅠ"],"q":[1,3]},"options":[{"t":"류","correct":true},{"t":"료","mis":"K1-1-u1-X02"},{"t":"루","mis":"K1-1-u1-X03"}],"explanation":["? 칸은 자음자 ㄹ 줄과 모음자 ㅠ 칸이 만나는 곳이에요.","ㄹ과 ㅠ가 만나면 「류」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":4,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄹ","ㅁ","ㅅ","ㅎ"],"vows":["ㅑ","ㅕ","ㅛ","ㅠ"],"mis":{"grid":"X07","flip":"X02","stroke":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#1','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',1,'mc','auto','책을 읽을 때 바른 자세는 어느 것인가요?',ARRAY['K1-1-u1-X10']::text[],true,'{"seq":1,"concept":"K1-1-u1-C5","difficulty":1,"kind":"mc","stem":"책을 읽을 때 바른 자세는 어느 것인가요?","options":[{"t":"등을 곧게 펴고 책과 눈 사이를 한 뼘쯤 띄워요","correct":true},{"t":"턱을 괴고 책에 얼굴을 바짝 대요","mis":"K1-1-u1-X10"},{"t":"바닥에 엎드려서 읽어요","mis":"K1-1-u1-X10"}],"explanation":["등을 펴고 한 뼘쯤 띄워야 눈과 허리가 편해요.","턱 괴기·엎드리기는 바른 자세가 아니에요.","등 펴기, 한 뼘."],"asset":{"type":"scene","icon":"📖"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책을 읽을 때 바른 자세는 어느 것인가요?","options":[{"t":"두 발을 바닥에 붙이고 허리를 펴고 앉아요","correct":true},{"t":"의자에 비스듬히 누워 읽어요","mis":"K1-1-u1-X10"},{"t":"다리를 꼬고 몸을 기울여 읽어요","mis":"K1-1-u1-X10"}],"explanation":["두 발은 바닥에, 허리는 곧게.","눕거나 기울이면 바른 자세가 아니에요.","등 펴기, 두 발 바닥."],"asset":{"type":"scene","icon":"📖"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#2','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',1,'mc','auto','글씨를 쓸 때 바른 자세는 어느 것인가요?',ARRAY['K1-1-u1-X11']::text[],true,'{"seq":2,"concept":"K1-1-u1-C5","difficulty":1,"kind":"mc","stem":"글씨를 쓸 때 바른 자세는 어느 것인가요?","options":[{"t":"연필을 바르게 쥐고 다른 손으로 공책을 눌러요","correct":true},{"t":"공책을 손에 들고 써요","mis":"K1-1-u1-X11"},{"t":"몸을 옆으로 기울여 써요","mis":"K1-1-u1-X11"}],"explanation":["공책을 눌러야 글씨가 흔들리지 않아요.","들고 쓰거나 기울이면 글씨가 삐뚤어져요.","쥔 손, 누른 손, 곧은 허리."],"asset":{"type":"scene","icon":"✏️"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글씨를 쓸 때 바른 자세는 어느 것인가요?","options":[{"t":"허리를 펴고 공책과 눈 사이를 알맞게 띄워요","correct":true},{"t":"공책에 얼굴을 바짝 대고 써요","mis":"K1-1-u1-X11"},{"t":"엎드려서 써요","mis":"K1-1-u1-X11"}],"explanation":["알맞게 띄워야 눈이 편해요.","얼굴을 대거나 엎드리면 바른 자세가 아니에요.","쥔 손, 누른 손, 곧은 허리."],"asset":{"type":"scene","icon":"✏️"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#3','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C2',1,'mc','auto','자음자 ㄱ과 모음자 ㅣ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X06','K1-1-u1-X04']::text[],true,'{"seq":3,"kind":"mc","stem":"자음자 ㄱ과 모음자 ㅣ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄱ","v":"ㅣ","s":null,"lay":true},"options":[{"t":"기","correct":true},{"t":"그","mis":"K1-1-u1-X06"},{"t":"키","mis":"K1-1-u1-X04"}],"explanation":["자음자 ㄱ과 모음자 ㅣ가 만나면 「기」예요.","ㅣ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅣ","ㅡ"],"mis":{"rot":"X06","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#4','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C2',1,'mc','auto','자음자 ㅎ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":4,"kind":"mc","stem":"자음자 ㅎ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅎ","v":"ㅏ","s":null,"lay":true},"options":[{"t":"하","correct":true},{"t":"허","mis":"K1-1-u1-X02"},{"t":"햐","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅎ과 모음자 ㅏ가 만나면 「하」예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅣ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#5','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',2,'ox','auto','소리 내어 읽을 때는 빨리 읽을수록 좋아요.',ARRAY['K1-1-u1-X15']::text[],true,'{"seq":5,"concept":"K1-1-u1-C5","difficulty":2,"kind":"ox","stem":"소리 내어 읽을 때는 빨리 읽을수록 좋아요.","answer":"X","reason_options":[{"t":"또박또박 읽어야 듣는 사람이 잘 알아들으니까","correct":true},{"t":"빨리 읽어야 책을 많이 읽으니까","mis":"K1-1-u1-X15"}],"mis":"K1-1-u1-X15","explanation":["또박또박 읽어요.","빨리만 읽으면 글자를 빠뜨려요.","글자 하나하나 정확하게."],"variant_rule":{"alt":[{"stem":"글자를 읽을 때 그림을 보고 짐작해서 읽어도 괜찮아요.","answer":"X","reason_options":[{"t":"글자 하나하나를 보고 읽어야 바르게 읽으니까","correct":true},{"t":"그림이 글자보다 더 정확하니까","mis":"K1-1-u1-X15"}],"explanation":["그림은 도움일 뿐이에요.","글자를 하나씩 짚으며 읽어요.","짐작하지 않기."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#6','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',2,'mc','auto','「가」를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X12']::text[],true,'{"seq":6,"concept":"K1-1-u1-C5","difficulty":2,"kind":"mc","stem":"「가」를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"ㄱ을 먼저 쓰고 ㅏ를 써요","correct":true},{"t":"ㅏ를 먼저 쓰고 ㄱ을 써요","mis":"K1-1-u1-X12"},{"t":"ㅏ의 짧은 획을 가장 먼저 써요","mis":"K1-1-u1-X12"}],"explanation":["자음자를 먼저, 모음자를 나중에 써요.","ㅏ는 긴 세로획 다음에 짧은 획.","자음자 먼저."],"variant_rule":{"alt":[{"stem":"「나」를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"ㄴ을 먼저 쓰고 ㅏ를 써요","correct":true},{"t":"ㅏ를 먼저 쓰고 ㄴ을 써요","mis":"K1-1-u1-X12"},{"t":"ㅏ의 짧은 획을 가장 먼저 써요","mis":"K1-1-u1-X12"}],"explanation":["자음자를 먼저, 모음자를 나중에 써요.","ㅏ는 긴 세로획 다음에 짧은 획.","자음자 먼저."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#7','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C5',2,'mc','auto','모음자 ㅏ를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X12']::text[],true,'{"seq":7,"concept":"K1-1-u1-C5","difficulty":2,"kind":"mc","stem":"모음자 ㅏ를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"긴 세로획을 위에서 아래로 긋고, 짧은 획을 왼쪽에서 오른쪽으로 그어요","correct":true},{"t":"짧은 획을 먼저 긋고, 긴 세로획을 나중에 그어요","mis":"K1-1-u1-X12"},{"t":"긴 세로획을 아래에서 위로 그어요","mis":"K1-1-u1-X12"}],"explanation":["긴 세로획이 먼저예요.","위에서 아래로, 왼쪽에서 오른쪽으로.","짧은 획은 나중에."],"variant_rule":{"alt":[{"stem":"모음자 ㅓ를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"짧은 획을 왼쪽에서 오른쪽으로 긋고, 긴 세로획을 위에서 아래로 그어요","correct":true},{"t":"긴 세로획을 먼저 긋고 짧은 획을 오른쪽에서 왼쪽으로 그어요","mis":"K1-1-u1-X12"},{"t":"긴 세로획을 아래에서 위로 그어요","mis":"K1-1-u1-X12"}],"explanation":["ㅓ는 짧은 획이 왼쪽에 있어 먼저 그어요.","왼쪽에서 오른쪽, 위에서 아래로.","쓰는 방향을 지켜요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_basic#8','kor',1,1,'u1','L07','g1_1_kor_u1_L07_basic','lesson_basic','K1-1-u1-C2',2,'mc','auto','ㄴ + ㅗ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X06']::text[],true,'{"seq":8,"kind":"mc","stem":"ㄴ + ㅗ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄴ","v":"ㅗ","s":null},"options":[{"t":"노","correct":true},{"t":"누","mis":"K1-1-u1-X02"},{"t":"나","mis":"K1-1-u1-X06"}],"explanation":["자음자 ㄴ과 모음자 ㅗ가 만나면 「노」예요.","ㅗ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅗ","ㅜ","ㅏ"],"mis":{"flip":"X02","rot":"X06","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
