INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#6','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C2',3,'mc','auto','ㅁ + ㅕ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":6,"kind":"mc","stem":"ㅁ + ㅕ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅁ","v":"ㅕ","s":null},"options":[{"t":"며","correct":true},{"t":"먀","mis":"K1-1-u1-X02"},{"t":"머","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅁ과 모음자 ㅕ가 만나면 「며」예요.","ㅕ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄴ","ㅁ","ㅅ","ㅇ","ㅎ"],"vows":["ㅑ","ㅕ","ㅛ","ㅠ"],"mis":{"flip":"X02","stroke":"X03","rot":"X06"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#7','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C7',3,'mc','auto','글자 카드 「모자」를 또박또박 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-1-u1-X02','K1-1-u1-X06']::text[],true,'{"seq":7,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"글자 카드 「모자」를 또박또박 바르게 읽은 것은 어느 것인가요?","options":[{"t":"모 · 자","correct":true},{"t":"머 · 자","mis":"K1-1-u1-X02"},{"t":"마 · 자","mis":"K1-1-u1-X06"}],"explanation":["ㅁ 아래에 ㅗ — 「모」, ㅈ 옆에 ㅏ — 「자」.","ㅓ나 ㅏ로 읽으면 모음자를 잘못 본 거예요.","글자마다 모음자를 보고 읽어요."],"asset":{"type":"scene","icon":"🎩"},"variant_rule":{"alt":[{"stem":"글자 카드 「두부」를 또박또박 바르게 읽은 것은 어느 것인가요?","options":[{"t":"두 · 부","correct":true},{"t":"도 · 부","mis":"K1-1-u1-X02"},{"t":"더 · 부","mis":"K1-1-u1-X06"}],"explanation":["ㄷ 아래에 ㅜ — 「두」.","ㅗ나 ㅓ로 읽으면 모음자를 잘못 본 거예요.","글자마다 모음자를 보고 읽어요."],"asset":{"type":"scene","icon":"🍲"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#8','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C5',4,'mc','auto','「소」를 쓰는 차례로 바른 것은 어느 것인가요?',ARRAY['K1-1-u1-X12']::text[],true,'{"seq":8,"concept":"K1-1-u1-C5","difficulty":4,"kind":"mc","stem":"「소」를 쓰는 차례로 바른 것은 어느 것인가요?","options":[{"t":"ㅅ → ㅗ의 짧은 세로획 → ㅗ의 긴 가로획","correct":true},{"t":"ㅗ의 긴 가로획 → ㅅ → ㅗ의 짧은 세로획","mis":"K1-1-u1-X12"},{"t":"ㅅ → ㅗ의 긴 가로획 → ㅗ의 짧은 세로획","mis":"K1-1-u1-X12"}],"explanation":["자음자 ㅅ을 먼저 써요.","ㅗ는 짧은 세로획, 긴 가로획 차례.","자음자 먼저, 위에서 아래로."],"variant_rule":{"alt":[{"stem":"「누」를 쓰는 차례로 바른 것은 어느 것인가요?","options":[{"t":"ㄴ → ㅜ의 긴 가로획 → ㅜ의 짧은 세로획","correct":true},{"t":"ㅜ의 짧은 세로획 → ㄴ → ㅜ의 긴 가로획","mis":"K1-1-u1-X12"},{"t":"ㄴ → ㅜ의 짧은 세로획 → ㅜ의 긴 가로획","mis":"K1-1-u1-X12"}],"explanation":["자음자 ㄴ을 먼저 써요.","ㅜ는 긴 가로획, 짧은 세로획 차례.","자음자 먼저, 위에서 아래로."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#9','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C5',4,'essay','teacher','바른 자세로 글씨를 써야 하는 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u1-C5","difficulty":4,"kind":"essay","stem":"바른 자세로 글씨를 써야 하는 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 바른 자세로 쓰면 글씨가 반듯하게 써져요. 오래 써도 허리와 눈이 덜 아파요. — 글씨(반듯함·알아보기 쉬움)와 몸(허리·눈·손)에 대한 까닭을 하나씩 대면 맞아요.","scoring_points":["글씨가 반듯해진다는 까닭이 있는가","몸(허리·눈·손)이 편하다는 까닭이 있는가","두 가지를 서로 다르게 썼는가"]},"explanation":["글씨가 반듯해져요.","몸이 덜 힘들어요.","까닭 두 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L07_challenge#10','kor',1,1,'u1','L07','g1_1_kor_u1_L07_challenge','lesson_challenge','K1-1-u1-C5',4,'mc','auto','또박또박 읽기를 돕는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X15','K1-1-u1-X10']::text[],false,'{"seq":10,"concept":"K1-1-u1-C5","difficulty":4,"kind":"mc","stem":"또박또박 읽기를 돕는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"손가락으로 글자를 하나씩 짚으며 읽어요","correct":true},{"t":"그림만 보고 내용을 짐작해 말해요","mis":"K1-1-u1-X15"},{"t":"책을 눈 가까이 대고 빨리 읽어요","mis":"K1-1-u1-X10"}],"explanation":["짚으며 읽으면 글자를 빠뜨리지 않아요.","짐작하거나 바짝 대고 빨리 읽으면 틀려요.","하나씩 짚기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
