INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#5','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C7',2,'mc','auto','그림에 알맞은 낱말 카드는 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X02']::text[],true,'{"seq":5,"concept":"K1-1-u1-C7","difficulty":2,"kind":"mc","stem":"그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"모자","correct":true},{"t":"자모","mis":"K1-1-u1-X09"},{"t":"무자","mis":"K1-1-u1-X02"}],"explanation":["머리에 쓰는 것은 「모자」예요.","「자모」는 차례가 바뀌었고, 「무자」는 ㅗ를 ㅜ로 썼어요.","그림 뜻 + 차례."],"asset":{"type":"scene","icon":"🎩"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"우유","correct":true},{"t":"유우","mis":"K1-1-u1-X09"},{"t":"오유","mis":"K1-1-u1-X02"}],"explanation":["하얀 마실 것은 「우유」예요.","「유우」는 차례가 바뀌었고, 「오유」는 ㅜ를 ㅗ로 썼어요.","그림 뜻 + 차례."],"asset":{"type":"scene","icon":"🥛"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#6','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C7',2,'mc','auto','그림에 알맞은 낱말 카드는 어느 것인가요?',ARRAY['K1-1-u1-X13','K1-1-u1-X04']::text[],true,'{"seq":6,"concept":"K1-1-u1-C7","difficulty":2,"kind":"mc","stem":"그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"해","correct":true},{"t":"헤","mis":"K1-1-u1-X13"},{"t":"애","mis":"K1-1-u1-X04"}],"explanation":["하늘에 뜬 해 — ㅎ과 ㅐ.","「헤」는 ㅐ를 ㅔ로, 「애」는 ㅎ을 ㅇ으로 썼어요.","자음자와 모음자 모두 보기."],"asset":{"type":"scene","icon":"☀️"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"배","correct":true},{"t":"베","mis":"K1-1-u1-X13"},{"t":"패","mis":"K1-1-u1-X04"}],"explanation":["물 위에 뜨는 배 — ㅂ과 ㅐ.","「베」는 ㅐ를 ㅔ로, 「패」는 ㅂ을 ㅍ으로 썼어요.","자음자와 모음자 모두 보기."],"asset":{"type":"scene","icon":"⛵"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#7','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C7',2,'match','auto','글자 카드를 차례대로 모아 만든 낱말을 바르게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"K1-1-u1-C7","difficulty":2,"kind":"match","stem":"글자 카드를 차례대로 모아 만든 낱말을 바르게 이으세요.","pairs":[{"l":"기 + 차","r":"기차"},{"l":"바 + 다","r":"바다"},{"l":"나 + 비","r":"나비"}],"mis":"K1-1-u1-X09","explanation":["카드 차례 그대로 모아요.","기 → 차, 바 → 다, 나 → 비.","왼쪽 카드부터."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글자 카드를 차례대로 모아 만든 낱말을 바르게 이으세요.","pairs":[{"l":"비 + 누","r":"비누"},{"l":"사 + 자","r":"사자"},{"l":"두 + 부","r":"두부"}],"explanation":["카드 차례 그대로 모아요.","비 → 누, 사 → 자, 두 → 부.","왼쪽 카드부터."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#8','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C2',2,'mc','auto','자음자 ㅈ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":8,"kind":"mc","stem":"자음자 ㅈ과 모음자 ㅏ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅈ","v":"ㅏ","s":null,"lay":true},"options":[{"t":"자","correct":true},{"t":"저","mis":"K1-1-u1-X02"},{"t":"쟈","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅈ과 모음자 ㅏ가 만나면 「자」예요.","ㅏ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":2,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅣ"],"mis":{"flip":"X02","stroke":"X03","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#9','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C7',2,'ox','auto','글자 카드 「리」와 「다」를 「리다」 차례로 모아도 「다리」가 돼요.',ARRAY['K1-1-u1-X09']::text[],true,'{"seq":9,"concept":"K1-1-u1-C7","difficulty":2,"kind":"ox","stem":"글자 카드 「리」와 「다」를 「리다」 차례로 모아도 「다리」가 돼요.","answer":"X","reason_options":[{"t":"모으는 차례가 바뀌면 다른 말이 되니까","correct":true},{"t":"같은 카드를 쓰면 차례는 상관없으니까","mis":"K1-1-u1-X09"}],"mis":"K1-1-u1-X09","explanation":["다리 ≠ 리다.","차례가 뜻을 바꿔요.","왼쪽부터 차례대로."],"variant_rule":{"alt":[{"stem":"글자 카드 「누」와 「비」를 「누비」 차례로 모아도 「비누」가 돼요.","answer":"X","reason_options":[{"t":"모으는 차례가 바뀌면 다른 말이 되니까","correct":true},{"t":"같은 카드를 쓰면 차례는 상관없으니까","mis":"K1-1-u1-X09"}],"explanation":["비누 ≠ 누비.","차례가 뜻을 바꿔요.","왼쪽부터 차례대로."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_basic#10','kor',1,1,'u1','L13','g1_1_kor_u1_L13_basic','lesson_basic','K1-1-u1-C7',3,'mc','auto','카드 ㅂ · ㅏ · ㅈ · ㅣ 네 장으로 만들 수 있는 입는 것은 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X08']::text[],true,'{"seq":10,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"카드 ㅂ · ㅏ · ㅈ · ㅣ 네 장으로 만들 수 있는 입는 것은 어느 것인가요?","options":[{"t":"바지","correct":true},{"t":"지바","mis":"K1-1-u1-X09"},{"t":"비자","mis":"K1-1-u1-X08"}],"explanation":["ㅂ+ㅏ = 바, ㅈ+ㅣ = 지 — 바지.","「지바」는 차례가 바뀌었고, 「비자」는 모음자 짝을 바꿨어요.","자음자마다 모음자 짝을 맞춰요."],"asset":{"type":"scene","icon":"👖"},"variant_rule":{"alt":[{"stem":"카드 ㅊ · ㅣ · ㅁ · ㅏ 네 장으로 만들 수 있는 입는 것은 어느 것인가요?","options":[{"t":"치마","correct":true},{"t":"마치","mis":"K1-1-u1-X09"},{"t":"차미","mis":"K1-1-u1-X08"}],"explanation":["ㅊ+ㅣ = 치, ㅁ+ㅏ = 마 — 치마.","「마치」는 차례가 바뀌었고, 「차미」는 모음자 짝을 바꿨어요.","자음자마다 모음자 짝을 맞춰요."],"asset":{"type":"scene","icon":"👗"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#1','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',2,'mc','auto','그림에 알맞은 낱말 카드는 어느 것인가요?',ARRAY['K1-1-u1-X13','K1-1-u1-X09']::text[],true,'{"seq":1,"concept":"K1-1-u1-C7","difficulty":2,"kind":"mc","stem":"그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"조개","correct":true},{"t":"조게","mis":"K1-1-u1-X13"},{"t":"개조","mis":"K1-1-u1-X09"}],"explanation":["바닷가의 조개 — 「개」의 모음자는 ㅐ.","「조게」는 ㅐ를 ㅔ로 썼고, 「개조」는 차례가 바뀌었어요.","모음자와 차례 모두."],"asset":{"type":"scene","icon":"🐚"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림에 알맞은 낱말 카드는 어느 것인가요?","options":[{"t":"돼지","correct":true},{"t":"되지","mis":"K1-1-u1-X14"},{"t":"지돼","mis":"K1-1-u1-X09"}],"explanation":["꿀꿀 돼지 — 「돼」의 모음자는 ㅙ.","「되지」는 ㅙ를 ㅚ로 썼고, 「지돼」는 차례가 바뀌었어요.","모음자와 차례 모두."],"asset":{"type":"scene","icon":"🐷"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#2','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C4',2,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X06','K1-1-u1-X07']::text[],true,'{"seq":2,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄱ","ㅋ","ㅌ"],"vows":["ㅏ","ㅗ","ㅣ"],"q":[1,1]},"options":[{"t":"코","correct":true},{"t":"카","mis":"K1-1-u1-X06"},{"t":"키","mis":"K1-1-u1-X07"}],"explanation":["? 칸은 자음자 ㅋ 줄과 모음자 ㅗ 칸이 만나는 곳이에요.","ㅋ과 ㅗ가 만나면 「코」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":2,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅁ","ㅂ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"grid":"X07","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#3','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',3,'mc','auto','카드 ㄷ · ㅗ · ㅌ · ㅗ · ㄹ · ㅣ 로 만든 낱말은 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X02']::text[],true,'{"seq":3,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"카드 ㄷ · ㅗ · ㅌ · ㅗ · ㄹ · ㅣ 로 만든 낱말은 어느 것인가요?","options":[{"t":"도토리","correct":true},{"t":"토도리","mis":"K1-1-u1-X09"},{"t":"도터리","mis":"K1-1-u1-X02"}],"explanation":["ㄷ+ㅗ, ㅌ+ㅗ, ㄹ+ㅣ — 도토리.","「토도리」는 차례가 바뀌었고, 「도터리」는 ㅗ를 ㅓ로 썼어요.","카드 차례대로 두 장씩."],"asset":{"type":"scene","icon":"🌰"},"variant_rule":{"alt":[{"stem":"카드 ㄱ · ㅗ · ㄱ · ㅜ · ㅁ · ㅏ 로 만든 낱말은 어느 것인가요?","options":[{"t":"고구마","correct":true},{"t":"구고마","mis":"K1-1-u1-X09"},{"t":"고고마","mis":"K1-1-u1-X02"}],"explanation":["ㄱ+ㅗ, ㄱ+ㅜ, ㅁ+ㅏ — 고구마.","「구고마」는 차례가 바뀌었고, 「고고마」는 ㅜ를 ㅗ로 썼어요.","카드 차례대로 두 장씩."],"asset":{"type":"scene","icon":"🍠"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#4','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',3,'error','auto','은우가 나비 그림을 보고 카드로 「비나」를 만들었어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X09','K1-1-u1-X02','K1-1-u1-X04']::text[],true,'{"seq":4,"concept":"K1-1-u1-C7","difficulty":3,"kind":"error","stem":"은우가 나비 그림을 보고 카드로 「비나」를 만들었어요. 무엇이 잘못되었나요?","options":[{"t":"글자를 모은 차례가 바뀌었어요 — 「나비」예요","correct":true,"mis_target":"K1-1-u1-X09"},{"t":"모음자 ㅏ를 ㅓ로 바꾸어야 해요","mis":"K1-1-u1-X02"},{"t":"자음자 ㄴ을 ㄷ으로 바꾸어야 해요","mis":"K1-1-u1-X04"}],"explanation":["카드는 맞게 골랐어요.","「나」를 먼저, 「비」를 나중에.","왼쪽부터 차례대로."],"asset":{"type":"scene","icon":"🦋"},"variant_rule":{"alt":[{"stem":"지안이가 기차 그림을 보고 카드로 「차기」를 만들었어요. 무엇이 잘못되었나요?","options":[{"t":"글자를 모은 차례가 바뀌었어요 — 「기차」예요","correct":true,"mis_target":"K1-1-u1-X09"},{"t":"모음자 ㅣ를 ㅡ로 바꾸어야 해요","mis":"K1-1-u1-X06"},{"t":"자음자 ㅊ을 ㅈ으로 바꾸어야 해요","mis":"K1-1-u1-X04"}],"explanation":["카드는 맞게 골랐어요.","「기」를 먼저, 「차」를 나중에.","왼쪽부터 차례대로."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#5','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C2',3,'mc','auto','ㅊ + ㅣ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X06','K1-1-u1-X04']::text[],true,'{"seq":5,"kind":"mc","stem":"ㅊ + ㅣ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅊ","v":"ㅣ","s":null},"options":[{"t":"치","correct":true},{"t":"츠","mis":"K1-1-u1-X06"},{"t":"지","mis":"K1-1-u1-X04"}],"explanation":["자음자 ㅊ과 모음자 ㅣ가 만나면 「치」예요.","ㅣ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㅊ","ㅈ","ㄱ","ㄷ","ㅂ","ㅎ"],"vows":["ㅣ","ㅡ"],"mis":{"rot":"X06","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#6','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',3,'mc','auto','글자 하나를 바꾸어 「나무」를 「나비」로 만들려면 어떻게 해야 할까요?',ARRAY['K1-1-u1-X09','K1-1-u1-X08']::text[],true,'{"seq":6,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"글자 하나를 바꾸어 「나무」를 「나비」로 만들려면 어떻게 해야 할까요?","options":[{"t":"「무」를 「비」로 바꿔요","correct":true},{"t":"「나」를 「비」로 바꿔요","mis":"K1-1-u1-X09"},{"t":"「무」의 ㅜ를 ㅣ로 바꿔요","mis":"K1-1-u1-X08"}],"explanation":["나무 → 나비: 둘째 글자가 바뀌어요.","ㅜ만 ㅣ로 바꾸면 「나미」가 돼요.","바뀌는 자리와 자음자까지."],"variant_rule":{"alt":[{"stem":"글자 하나를 바꾸어 「바다」를 「바지」로 만들려면 어떻게 해야 할까요?","options":[{"t":"「다」를 「지」로 바꿔요","correct":true},{"t":"「바」를 「지」로 바꿔요","mis":"K1-1-u1-X09"},{"t":"「다」의 ㅏ를 ㅣ로 바꿔요","mis":"K1-1-u1-X08"}],"explanation":["바다 → 바지: 둘째 글자가 바뀌어요.","ㅏ만 ㅣ로 바꾸면 「바디」가 돼요.","바뀌는 자리와 자음자까지."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#7','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',3,'sa','auto','그림에 알맞은 낱말을 카드 ㅎ · ㅏ · ㅁ · ㅏ 로 만들어 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"K1-1-u1-C7","difficulty":3,"kind":"sa","stem":"그림에 알맞은 낱말을 카드 ㅎ · ㅏ · ㅁ · ㅏ 로 만들어 쓰세요.","answer":["하마"],"explanation":["ㅎ+ㅏ = 하, ㅁ+ㅏ = 마.","차례대로 모으면 「하마」.","카드 두 장씩 모아요."],"asset":{"type":"scene","icon":"🦛"},"variant_rule":{"alt":[{"stem":"그림에 알맞은 낱말을 카드 ㅅ · ㅏ · ㅈ · ㅏ 로 만들어 쓰세요.","answer":["사자"],"explanation":["ㅅ+ㅏ = 사, ㅈ+ㅏ = 자.","차례대로 모으면 「사자」.","카드 두 장씩 모아요."],"asset":{"type":"scene","icon":"🦁"}},{"stem":"그림에 알맞은 낱말을 카드 ㅇ · ㅕ · ㅇ · ㅜ 로 만들어 쓰세요.","answer":["여우"],"explanation":["ㅇ+ㅕ = 여, ㅇ+ㅜ = 우.","차례대로 모으면 「여우」.","카드 두 장씩 모아요."],"asset":{"type":"scene","icon":"🦊"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#8','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',4,'mc','auto','글자 카드 「고」, 「구」, 「마」 세 장을 모두 써서 만든 낱말은 어느 것인가요?',ARRAY['K1-1-u1-X09']::text[],true,'{"seq":8,"concept":"K1-1-u1-C7","difficulty":4,"kind":"mc","stem":"글자 카드 「고」, 「구」, 「마」 세 장을 모두 써서 만든 낱말은 어느 것인가요?","options":[{"t":"고구마","correct":true},{"t":"구고마","mis":"K1-1-u1-X09"},{"t":"고마구","mis":"K1-1-u1-X09"}],"explanation":["고 → 구 → 마, 고구마.","다른 것은 차례가 바뀌었어요.","뜻이 되는 차례 찾기."],"asset":{"type":"scene","icon":"🍠"},"variant_rule":{"alt":[{"stem":"글자 카드 「리」, 「다」, 「미」 세 장을 모두 써서 만든 낱말은 어느 것인가요?","options":[{"t":"다리미","correct":true},{"t":"리다미","mis":"K1-1-u1-X09"},{"t":"다미리","mis":"K1-1-u1-X09"}],"explanation":["다 → 리 → 미, 다리미.","다른 것은 차례가 바뀌었어요.","뜻이 되는 차례 찾기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#9','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C7',4,'essay','teacher','자음자 카드 ㄱ · ㄴ 과 모음자 카드 ㅏ · ㅜ 를 여러 번 써서 낱말을 두 개 만들고, 또박또박 읽어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u1-C7","difficulty":4,"kind":"essay","stem":"자음자 카드 ㄱ · ㄴ 과 모음자 카드 ㅏ · ㅜ 를 여러 번 써서 낱말을 두 개 만들고, 또박또박 읽어 보세요.","answer_guide":{"answer":"예: 「누나」(ㄴ+ㅜ, ㄴ+ㅏ)와 「가구」(ㄱ+ㅏ, ㄱ+ㅜ). — 뜻이 있는 낱말 두 개를 만들고 글자마다 자음자+모음자를 바르게 모았으면 맞아요.","scoring_points":["뜻이 있는 낱말을 두 개 만들었는가","글자마다 자음자와 모음자를 바르게 모았는가","글자를 차례대로 또박또박 읽었는가"]},"explanation":["누나·가구처럼 만들어요.","글자마다 자음자 + 모음자.","차례대로 또박또박."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_L13_challenge#10','kor',1,1,'u1','L13','g1_1_kor_u1_L13_challenge','lesson_challenge','K1-1-u1-C4',4,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":10,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄴ","ㅂ","ㅍ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"q":[2,3]},"options":[{"t":"푸","correct":true},{"t":"포","mis":"K1-1-u1-X02"},{"t":"퓨","mis":"K1-1-u1-X03"}],"explanation":["? 칸은 자음자 ㅍ 줄과 모음자 ㅜ 칸이 만나는 곳이에요.","ㅍ과 ㅜ가 만나면 「푸」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":4,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅂ","ㅍ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅕ"],"mis":{"grid":"X07","flip":"X02","stroke":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#1','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C1',1,'mc','auto','「보」에서 자음자는 어느 것인가요?',ARRAY['K1-1-u1-X01','K1-1-u1-X04']::text[],true,'{"seq":1,"kind":"mc","stem":"「보」에서 자음자는 어느 것인가요?","asset":{"type":"jamo","s":"보","eq":false,"lay":"blank"},"options":[{"t":"ㅂ","correct":true},{"t":"ㅗ","mis":"K1-1-u1-X01"},{"t":"ㅍ","mis":"K1-1-u1-X04"}],"explanation":["「보」는 자음자 ㅂ과 모음자 ㅗ가 만난 글자예요.","자음자는 ㅂ이에요 — 위쪽에 있어요.","글자를 둘로 나누어 자음자와 모음자를 찾아요."],"concept":"K1-1-u1-C1","difficulty":1,"variant_rule":{"jamo":{"ask":"cons","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"role":"X01","cons":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#2','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C1',1,'mc','auto','다음 가운데 모음자는 어느 것인가요?',ARRAY['K1-1-u1-X01']::text[],false,'{"seq":2,"concept":"K1-1-u1-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 모음자는 어느 것인가요?","options":[{"t":"ㅓ","correct":true},{"t":"ㄷ","mis":"K1-1-u1-X01"},{"t":"ㅎ","mis":"K1-1-u1-X01"}],"explanation":["ㅓ는 모음자예요.","ㄷ·ㅎ은 자음자예요.","모음자는 막대 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#3','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C2',1,'mc','auto','자음자 ㄱ과 모음자 ㅗ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":3,"kind":"mc","stem":"자음자 ㄱ과 모음자 ㅗ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㄱ","v":"ㅗ","s":null,"lay":true},"options":[{"t":"고","correct":true},{"t":"구","mis":"K1-1-u1-X02"},{"t":"교","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㄱ과 모음자 ㅗ가 만나면 「고」예요.","ㅗ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"mis":{"flip":"X02","stroke":"X03","rot":"X06","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#4','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C3',1,'mc','auto','「소」에서 자음자 ㅅ은 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":4,"kind":"mc","stem":"「소」에서 자음자 ㅅ은 어디에 있나요?","asset":{"type":"jamo","s":"소","eq":false},"options":[{"t":"위쪽","correct":true},{"t":"왼쪽","mis":"K1-1-u1-X05"},{"t":"아래쪽","mis":"K1-1-u1-X01"}],"explanation":["「소」는 위아래로 쌓아서 만든 글자예요.","ㅗ는 가로로 길어서 자음자 아래에 쌓여요.","그래서 자음자 ㅅ은 위쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":1,"variant_rule":{"jamo":{"ask":"place","role":"c","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_a#5','kor',1,1,'u1','','g1_1_kor_u1_review_a','unit_review','K1-1-u1-C4',1,'mc','auto','음절표에서 ? 칸에 들어갈 글자는 무엇인가요?',ARRAY['K1-1-u1-X06','K1-1-u1-X07']::text[],true,'{"seq":5,"kind":"mc","stem":"음절표에서 ? 칸에 들어갈 글자는 무엇인가요?","asset":{"type":"syl_table","cons":["ㄱ","ㄴ","ㄷ"],"vows":["ㅏ","ㅗ","ㅣ"],"q":[2,0]},"options":[{"t":"다","correct":true},{"t":"도","mis":"K1-1-u1-X06"},{"t":"디","mis":"K1-1-u1-X07"}],"explanation":["? 칸은 자음자 ㄷ 줄과 모음자 ㅏ 칸이 만나는 곳이에요.","ㄷ과 ㅏ가 만나면 「다」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":1,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄷ","ㅁ","ㅂ","ㅅ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ"],"mis":{"grid":"X07","rot":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
