INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#12','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C3',2,'mc','auto','위아래로 쌓아서 만든 글자는 어느 것인가요?',ARRAY['K1-1-u1-X05']::text[],false,'{"seq":12,"concept":"K1-1-u1-C3","difficulty":2,"kind":"mc","stem":"위아래로 쌓아서 만든 글자는 어느 것인가요?","options":[{"t":"투","correct":true},{"t":"타","mis":"K1-1-u1-X05"},{"t":"티","mis":"K1-1-u1-X05"}],"explanation":["「투」는 ㅌ 아래에 ㅜ.","「타」·「티」는 옆으로 나란히.","가로로 긴 모음자는 아래에."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#13','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C4',2,'mc','auto','음절표에서 ㅎ 줄을 따라 차례대로 읽은 것은 어느 것인가요?',ARRAY['K1-1-u1-X07','K1-1-u1-X02']::text[],false,'{"seq":13,"concept":"K1-1-u1-C4","difficulty":2,"kind":"mc","stem":"음절표에서 ㅎ 줄을 따라 차례대로 읽은 것은 어느 것인가요?","options":[{"t":"하 · 허 · 호 · 후","correct":true},{"t":"라 · 마 · 하","mis":"K1-1-u1-X07"},{"t":"하 · 허 · 후 · 호","mis":"K1-1-u1-X02"}],"explanation":["ㅎ 줄은 하·허·호·후예요.","다른 하나는 ㅏ 칸을 위에서 아래로 읽은 거예요.","줄은 옆으로 읽어요."],"asset":{"type":"syl_table","cons":["ㄹ","ㅁ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#14','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C5',2,'mc','auto','「나」를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u1-X12']::text[],false,'{"seq":14,"concept":"K1-1-u1-C5","difficulty":2,"kind":"mc","stem":"「나」를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"ㄴ을 먼저 쓰고 ㅏ를 써요","correct":true},{"t":"ㅏ를 먼저 쓰고 ㄴ을 써요","mis":"K1-1-u1-X12"},{"t":"ㄴ을 아래에서 위로 써요","mis":"K1-1-u1-X12"}],"explanation":["자음자를 먼저, 모음자를 나중에.","모음자의 획도 위에서 아래로, 왼쪽에서 오른쪽으로.","자음자 먼저."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#15','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C6',2,'match','auto','두 모음자를 합쳐 만든 모음자를 바르게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K1-1-u1-C6","difficulty":2,"kind":"match","stem":"두 모음자를 합쳐 만든 모음자를 바르게 이으세요.","pairs":[{"l":"ㅜ + ㅔ","r":"ㅞ"},{"l":"ㅗ + ㅏ","r":"ㅘ"},{"l":"ㅜ + ㅣ","r":"ㅟ"}],"mis":"K1-1-u1-X14","explanation":["두 모음자를 다 봐요.","앞의 모음자 + 뒤의 모음자.","합친 모음자 = 두 모음자."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#16','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C6',2,'ox','auto','「베개」의 「베」에는 모음자 ㅐ가 들어 있어요.',ARRAY['K1-1-u1-X13']::text[],false,'{"seq":16,"concept":"K1-1-u1-C6","difficulty":2,"kind":"ox","stem":"「베개」의 「베」에는 모음자 ㅐ가 들어 있어요.","answer":"X","reason_options":[{"t":"「베」는 ㅂ과 ㅔ가 만난 글자니까","correct":true},{"t":"두 글자의 모음자는 늘 같으니까","mis":"K1-1-u1-X13"}],"mis":"K1-1-u1-X13","explanation":["베 = ㅂ + ㅔ, 개 = ㄱ + ㅐ.","두 글자 모음자가 달라요.","글자마다 따로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#17','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C1',3,'ox','auto','「이」는 모음자 ㅣ 하나로만 된 글자예요.',ARRAY['K1-1-u1-X16']::text[],false,'{"seq":17,"concept":"K1-1-u1-C1","difficulty":3,"kind":"ox","stem":"「이」는 모음자 ㅣ 하나로만 된 글자예요.","answer":"X","reason_options":[{"t":"「이」에는 자음자 ㅇ도 있으니까","correct":true},{"t":"ㅇ은 소리가 없어서 자음자가 아니니까","mis":"K1-1-u1-X16"}],"mis":"K1-1-u1-X16","explanation":["이 = ㅇ + ㅣ.","ㅇ은 소리가 없어도 자음자 자리를 채워요.","아·오·이·우에도 ㅇ."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#18','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C2',3,'error','auto','예나가 자음자 ㄴ과 모음자 ㅜ를 모아 「뉴」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X03','K1-1-u1-X04','K1-1-u1-X02']::text[],false,'{"seq":18,"concept":"K1-1-u1-C2","difficulty":3,"kind":"error","stem":"예나가 자음자 ㄴ과 모음자 ㅜ를 모아 「뉴」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"짧은 획을 하나 더 썼어요 — ㄴ과 ㅜ는 「누」예요","correct":true,"mis_target":"K1-1-u1-X03"},{"t":"자음자를 ㄷ으로 써야 해요 — 「두」예요","mis":"K1-1-u1-X04"},{"t":"모음자의 방향을 바꾸어 썼어요 — 「노」예요","mis":"K1-1-u1-X02"}],"explanation":["ㄴ + ㅜ = 누.","「뉴」와 「누」는 다른 글자예요.","자음자와 모음자를 하나씩 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#19','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C3',3,'error','auto','지후가 「부」를 쓸 때 ㅜ를 ㅂ 오른쪽에 붙여 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X02','K1-1-u1-X04']::text[],false,'{"seq":19,"concept":"K1-1-u1-C3","difficulty":3,"kind":"error","stem":"지후가 「부」를 쓸 때 ㅜ를 ㅂ 오른쪽에 붙여 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅜ는 ㅂ 아래쪽에 써야 해요","correct":true,"mis_target":"K1-1-u1-X05"},{"t":"ㅜ 대신 ㅗ를 써야 해요","mis":"K1-1-u1-X02"},{"t":"ㅂ 대신 ㅍ을 써야 해요","mis":"K1-1-u1-X04"}],"explanation":["ㅜ는 가로로 길어서 아래에 쌓여요.","모음자는 맞게 골랐고 자리만 틀렸어요.","모음자 모양이 자리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#20','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C6',3,'mc','auto','ㅎ + ㅚ 는 어떤 글자가 되나요?',ARRAY['K1-1-u1-X14']::text[],true,'{"seq":20,"kind":"mc","stem":"ㅎ + ㅚ 는 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅎ","v":"ㅚ","s":null},"options":[{"t":"회","correct":true},{"t":"호","mis":"K1-1-u1-X14"},{"t":"히","mis":"K1-1-u1-X14"}],"explanation":["자음자 ㅎ과 모음자 ㅚ가 만나면 「회」예요.","ㅚ는 자음자의 아래와 오른쪽을 함께 감싸요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C6","difficulty":3,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅐ","ㅔ","ㅒ","ㅖ","ㅘ","ㅝ","ㅚ","ㅟ","ㅙ","ㅢ"],"mis":{"ae":"X13","comb":"X14","cons":"X04"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_c#21','kor',1,1,'u1','','g1_1_kor_u1_review_c','unit_review','K1-1-u1-C7',3,'mc','auto','카드 ㄱ · ㅣ · ㅊ · ㅏ 네 장으로 만들 수 있는 탈것은 어느 것인가요?',ARRAY['K1-1-u1-X09','K1-1-u1-X08']::text[],false,'{"seq":21,"concept":"K1-1-u1-C7","difficulty":3,"kind":"mc","stem":"카드 ㄱ · ㅣ · ㅊ · ㅏ 네 장으로 만들 수 있는 탈것은 어느 것인가요?","options":[{"t":"기차","correct":true},{"t":"차기","mis":"K1-1-u1-X09"},{"t":"가치","mis":"K1-1-u1-X08"}],"explanation":["ㄱ+ㅣ = 기, ㅊ+ㅏ = 차 — 기차.","「차기」는 차례가 바뀌었고, 「가치」는 모음자 짝을 바꿨어요.","자음자마다 모음자 짝을 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
