INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#3','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C2',1,'mc','auto','자음자 ㅅ과 모음자 ㅜ가 만나면 어떤 글자가 되나요?',ARRAY['K1-1-u1-X02','K1-1-u1-X03']::text[],true,'{"seq":3,"kind":"mc","stem":"자음자 ㅅ과 모음자 ㅜ가 만나면 어떤 글자가 되나요?","asset":{"type":"jamo","c":"ㅅ","v":"ㅜ","s":null,"lay":true},"options":[{"t":"수","correct":true},{"t":"소","mis":"K1-1-u1-X02"},{"t":"슈","mis":"K1-1-u1-X03"}],"explanation":["자음자 ㅅ과 모음자 ㅜ가 만나면 「수」예요.","ㅜ는 가로로 길어서 자음자 아래에 쌓여요.","자음자 소리와 모음자 소리를 이어서 천천히 읽어 봐요."],"concept":"K1-1-u1-C2","difficulty":1,"variant_rule":{"jamo":{"ask":"build","cons":["ㄱ","ㄷ","ㅂ","ㅈ","ㅅ","ㅁ","ㄴ","ㅎ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ"],"mis":{"flip":"X02","stroke":"X03","rot":"X06","cons":"X04"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#4','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C3',1,'mc','auto','「버」에서 자음자 ㅂ은 어디에 있나요?',ARRAY['K1-1-u1-X05','K1-1-u1-X01']::text[],true,'{"seq":4,"kind":"mc","stem":"「버」에서 자음자 ㅂ은 어디에 있나요?","asset":{"type":"jamo","s":"버","eq":false},"options":[{"t":"왼쪽","correct":true},{"t":"위쪽","mis":"K1-1-u1-X05"},{"t":"오른쪽","mis":"K1-1-u1-X01"}],"explanation":["「버」는 옆으로 나란히 만든 글자예요.","ㅓ는 세로로 길어서 자음자 오른쪽에 나란히 서요.","그래서 자음자 ㅂ은 왼쪽에 있어요."],"concept":"K1-1-u1-C3","difficulty":1,"variant_rule":{"jamo":{"ask":"place","role":"c","cons":["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅈ"],"vows":["ㅏ","ㅓ","ㅗ","ㅜ","ㅣ","ㅡ"],"mis":{"place":"X05","role":"X01"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
