INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#23','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C4',4,'sa','auto','음절표에서 ? 칸에 들어갈 글자를 쓰세요.','{}'::text[],true,'{"seq":23,"kind":"sa","stem":"음절표에서 ? 칸에 들어갈 글자를 쓰세요.","asset":{"type":"syl_table","cons":["ㄹ","ㅂ","ㅅ","ㅈ"],"vows":["ㅑ","ㅓ","ㅗ","ㅣ"],"q":[2,0]},"answer":["샤"],"explanation":["? 칸은 자음자 ㅅ 줄과 모음자 ㅑ 칸이 만나는 곳이에요.","ㅅ과 ㅑ가 만나면 「샤」예요.","왼쪽 자음자 줄을 따라가다 위쪽 모음자 칸에서 멈춰요."],"concept":"K1-1-u1-C4","difficulty":4,"variant_rule":{"jamo":{"ask":"table","cons":["ㄱ","ㄴ","ㄹ","ㅁ","ㅅ","ㅎ"],"vows":["ㅑ","ㅕ","ㅛ","ㅠ"],"mis":{"grid":"X07","flip":"X02","stroke":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#24','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C7',4,'essay','teacher','카드 ㅅ · ㅈ · ㅏ · ㅜ 를 골라 낱말을 두 개 만들고, 글자마다 어떤 자음자와 모음자를 모았는지 말해 보세요. (카드는 여러 번 써도 돼요)','{}'::text[],false,'{"seq":24,"concept":"K1-1-u1-C7","difficulty":4,"kind":"essay","stem":"카드 ㅅ · ㅈ · ㅏ · ㅜ 를 골라 낱말을 두 개 만들고, 글자마다 어떤 자음자와 모음자를 모았는지 말해 보세요. (카드는 여러 번 써도 돼요)","answer_guide":{"answer":"예: 「사자」(ㅅ+ㅏ, ㅈ+ㅏ)와 「주사」(ㅈ+ㅜ, ㅅ+ㅏ) — 뜻이 있는 낱말 두 개를 만들고 글자마다 자음자+모음자를 바르게 말하면 맞아요.","scoring_points":["뜻이 있는 낱말을 두 개 만들었는가","글자마다 자음자와 모음자를 바르게 말했는가","글자를 차례대로 모았는가"]},"explanation":["낱말 두 개.","글자마다 자음자 + 모음자.","차례대로 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u1_review_d#25','kor',1,1,'u1','','g1_1_kor_u1_review_d','unit_review','K1-1-u1-C2',4,'mc','auto','카드 ㅈ · ㅎ · ㅏ · ㅡ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?',ARRAY['K1-1-u1-X04','K1-1-u1-X01']::text[],false,'{"seq":25,"concept":"K1-1-u1-C2","difficulty":4,"kind":"mc","stem":"카드 ㅈ · ㅎ · ㅏ · ㅡ 가운데 두 장을 골라 만들 수 없는 글자는 어느 것인가요?","options":[{"t":"차","correct":true},{"t":"자","mis":"K1-1-u1-X04"},{"t":"흐","mis":"K1-1-u1-X01"}],"explanation":["「차」에 필요한 카드가 없어요.","「자」와 「흐」는 만들 수 있어요.","자음자 하나 + 모음자 하나."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
